#define NS_sendto(s_, b, n, f, a, l)  sendto(s_, b, n, f, a, l)
#define NS_recvfrom(s_, b, n, f, a, l) recvfrom(s_, b, n, f, a, l)
#define NS_close(s_)                  close(s_)
#define NS_setsockopt(s_, l, o, v, n) setsockopt(s_, l, o, v, n)
#endif
