static int   pl_spw[MAXP];         // caido: 0 = tu vista, k>0 = espectea al jugador k-1 (ARRIBA / ABAJO)
static int   rv_tgt[MAXP];         // a quien esta reviviendo cada jugador (-1 = a nadie)
