// Tumbas: monumento con cruz (modelo A) y lapida con arco (modelo B)
static void draw_grave(float x, float z, float a, float h, int mono, const float *col)
{
    const short (*gv)[3] = mono ? ga_v : gb_v;
    const unsigned char (*gt)[4] = mono ? ga_t : gb_t;
    int nv = mono ? GA_NV : GB_NV, nt = mono ? GA_NT : GB_NT;
    static V vv[GA_NV];
    static const float white[3] = { 1.0f, 1.0f, 1.0f };
    float ca = cosf(a), sa = sinf(a), k = h * 0.001f;
    for (int i = 0; i < nv; i++) {
        float lx = (float)gv[i][0] * k, lz = (float)gv[i][2] * k;
        vv[i] = mk(x + lx * ca + lz * sa, (float)gv[i][1] * k, z - lx * sa + lz * ca, white, 0.0f);
    }
    for (int j = 0; j < nt; j++) {
        float sh = (float)gt[j][3] / 255.0f;
        V v[3];
        for (int m = 0; m < 3; m++) {
            v[m] = vv[gt[j][m]];
            v[m].r *= col[0] * sh; v[m].g *= col[1] * sh; v[m].b *= col[2] * sh;
        }
        tri_cam(v[0], v[1], v[2]);
    }
}
static void draw_graves(void)
{
    if (cur_layer != 0 && !climbing) return;
    float lim = fminf(draw_lim, (gfx_pd[gfx] * rd_k));
    for (int i = 0; i < NGRAVE; i++) {
        if (!in_view(graves[i].x, graves[i].z, 1.2f, lim)) continue;
        float col[3] = { (float)graves[i].r, (float)graves[i].g, (float)graves[i].b };
        if (graves[i].mono) { col[0] = 150.f; col[1] = 150.f; col[2] = 156.f; }
        draw_grave(graves[i].x, graves[i].z, graves[i].a, graves[i].h, graves[i].mono, col);
    }
}

