// Caseta de la antena (paredes en las celdas x 172..184, z 164..176; la entrada da al sur): techo a dos aguas de tejas con aleros y porche,
// zocalo de piedra, esquineros de madera, ventana con postigos y jardinera, letrero colgante "ANTENA", faroles, mastil con luz roja,
// chimenea, equipo de aire en el suelo y cable hasta la torre.
static void draw_hut(float t)
{
    if (cur_layer != 0 && !climbing) return;
    if (!in_view(178.0f, 170.0f, 17.0f, fminf(draw_lim, (gfx_pd[gfx] * rd_k)))) return;
    static const float stone[3] = { 112.f, 108.f, 104.f }, wood[3] = { 66.f, 44.f, 30.f }, woodl[3] = { 150.f, 112.f, 74.f };
    static const float tile0[3] = { 150.f, 74.f, 54.f }, tile1[3] = { 128.f, 60.f, 46.f }, cap[3] = { 78.f, 40.f, 34.f };
    static const float teal[3] = { 58.f, 122.f, 122.f }, board[3] = { 176.f, 150.f, 112.f }, blk[3] = { 26.f, 26.f, 30.f };
    static const float cyan[3] = { 90.f, 230.f, 255.f }, lamp[3] = { 255.f, 206.f, 120.f }, redc[3] = { 255.f, 40.f, 40.f };
    static const float ac[3] = { 168.f, 172.f, 176.f }, cab[3] = { 30.f, 30.f, 34.f }, ebox[3] = { 100.f, 108.f, 100.f }, yel[3] = { 240.f, 200.f, 40.f };
    static const float fl[4][3] = { { 220.f, 50.f, 60.f }, { 240.f, 200.f, 60.f }, { 235.f, 120.f, 170.f }, { 250.f, 250.f, 250.f } }, leaf[3] = { 48.f, 120.f, 60.f };
    const float X0 = 172.0f, X1 = 184.0f, Z0 = 164.0f, Z1 = 176.0f, YE = 3.15f, YR = 5.5f, RZ = 7.1f, RX0 = 170.9f, RX1 = 185.1f;
    float ddx = px - 178.0f, ddz = pz - 170.0f, d2 = ddx * ddx + ddz * ddz;
    // techo a dos aguas: 7 hileras de tejas por faldon, alternando tono
    for (int sd = 0; sd < 2; sd++)
        for (int i = 0; i < 7; i++) {
            float t0 = (float)i / 7.0f, t1 = (float)(i + 1) / 7.0f;
            float z0 = sd ? 170.0f + RZ * (1.0f - t0) : 170.0f - RZ * (1.0f - t0);
            float z1 = sd ? 170.0f + RZ * (1.0f - t1) : 170.0f - RZ * (1.0f - t1);
            float y0 = YE + (YR - YE) * t0, y1 = YE + (YR - YE) * t1;
            float q[4][3] = { { RX0, y0, z0 }, { RX1, y0, z0 }, { RX1, y1, z1 }, { RX0, y1, z1 } };
            quad_sub(q, (i & 1) ? tile1 : tile0, 2, 0.0f);
        }
    box_rot(178.0f, 170.0f, 0, 0, 0, 7.25f, 0.2f, YR - 0.06f, YR + 0.14f, cap, 0.0f);          // cumbrera
    box_rot(178.0f, 170.0f - RZ + 0.02f, 0, 0, 0, 7.2f, 0.05f, YE - 0.2f, YE + 0.05f, wood, 0.0f);   // tablas de alero (frente y fondo)
    box_rot(178.0f, 170.0f + RZ - 0.02f, 0, 0, 0, 7.2f, 0.05f, YE - 0.2f, YE + 0.05f, wood, 0.0f);
    box_rot(178.0f, 170.0f - RZ - 0.04f, 0, 0, 0, 7.2f, 0.04f, YE - 0.06f, YE + 0.03f, cab, 0.0f);   // canalon
    box_rot(178.0f, 170.0f + RZ + 0.04f, 0, 0, 0, 7.2f, 0.04f, YE - 0.06f, YE + 0.03f, cab, 0.0f);
    // frontones de madera en los costados (triangulos sobre las paredes) con respiradero
    for (int e = 0; e < 2; e++) {
        float gx = e ? X1 + 0.02f : X0 - 0.02f;
        float q[4][3] = { { gx, 3.2f, 163.15f }, { gx, 3.2f, 176.85f }, { gx, YR - 0.12f, 170.0f }, { gx, YR - 0.12f, 170.0f } };
        quad_sub(q, board, 2, 0.0f);
        box_rot(gx + (e ? 0.03f : -0.03f), 170.0f, 0, 0, 0, 0.03f, 0.32f, 3.85f, 4.5f, wood, 0.0f);
    }
    // zocalo de piedra y esquineros de madera, cinta bajo el alero
    if (d2 < 60.0f * 60.0f) {
        box_rot(X0 - 0.05f, 170.0f, 0, 0, 0, 0.06f, 6.05f, 0.0f, 0.5f, stone, 0.0f);
        box_rot(X1 + 0.05f, 170.0f, 0, 0, 0, 0.06f, 6.05f, 0.0f, 0.5f, stone, 0.0f);
        box_rot(178.0f, Z0 - 0.05f, 0, 0, 0, 6.05f, 0.06f, 0.0f, 0.5f, stone, 0.0f);
        box_rot(174.0f, Z1 + 0.05f, 0, 0, 0, 2.05f, 0.06f, 0.0f, 0.5f, stone, 0.0f);
        box_rot(182.0f, Z1 + 0.05f, 0, 0, 0, 2.05f, 0.06f, 0.0f, 0.5f, stone, 0.0f);
    }
    for (int cx = 0; cx < 2; cx++)
        for (int cz = 0; cz < 2; cz++) box_rot(cx ? X1 : X0, cz ? Z1 : Z0, 0, 0, 0, 0.16f, 0.16f, 0.0f, 3.25f, wood, 0.0f);
    box_rot(X0 - 0.03f, 170.0f, 0, 0, 0, 0.05f, 6.0f, 3.0f, 3.2f, wood, 0.0f);
    box_rot(X1 + 0.03f, 170.0f, 0, 0, 0, 0.05f, 6.0f, 3.0f, 3.2f, wood, 0.0f);
    box_rot(178.0f, Z0 - 0.03f, 0, 0, 0, 6.0f, 0.05f, 3.0f, 3.2f, wood, 0.0f);
    // ventana del norte: marco, alfeizar, postigos turquesa y jardinera con flores
    box_rot(178.0f, Z0 - 0.08f, 0, 0, 0, 1.25f, 0.07f, 0.88f, 1.0f, wood, 0.0f);
    box_rot(178.0f, Z0 - 0.06f, 0, 0, 0, 1.15f, 0.05f, 2.2f, 2.34f, wood, 0.0f);
    box_rot(176.9f, Z0 - 0.05f, 0, 0, 0, 0.06f, 0.05f, 1.0f, 2.2f, wood, 0.0f);
    box_rot(179.1f, Z0 - 0.05f, 0, 0, 0, 0.06f, 0.05f, 1.0f, 2.2f, wood, 0.0f);
    box_rot(176.5f, Z0 - 0.06f, 0, 0, 0, 0.32f, 0.04f, 1.0f, 2.2f, teal, 0.0f);
    box_rot(179.5f, Z0 - 0.06f, 0, 0, 0, 0.32f, 0.04f, 1.0f, 2.2f, teal, 0.0f);
    box_rot(178.0f, Z0 - 0.3f, 0, 0, 0, 1.2f, 0.2f, 0.56f, 0.88f, wood, 0.0f);
    for (int k = 0; k < 7; k++) box_rot(177.0f + 0.33f * (float)k, Z0 - 0.3f, 0, 0, 0, 0.12f, 0.12f, 0.88f, 1.16f, (k & 1) ? fl[k % 4] : leaf, 0.0f);
    // entrada: postes del porche, letrero colgante ANTENA, faroles, escalones, felpudo
    for (int s2 = 0; s2 < 2; s2++) {
        float px2 = s2 ? 179.75f : 176.25f;
        box_rot(px2, 176.9f, 0, 0, 0, 0.13f, 0.13f, 0.0f, YE + 0.05f, wood, 0.0f);
        box_rot(px2, 176.9f, 0, 0, 0, 0.2f, 0.2f, 0.0f, 0.18f, stone, 0.0f);
        float fk = 0.85f + 0.15f * sinf(t * 11.0f + (float)s2 * 2.0f);
        box_rot(px2 + (s2 ? -0.2f : 0.2f), 176.9f, 0, 0, 0, 0.04f, 0.04f, 2.25f, 2.7f, blk, 0.0f);
        box_rot(px2 + (s2 ? -0.32f : 0.32f), 176.9f, 0, 0, 0, 0.11f, 0.11f, 2.1f, 2.45f, lamp, 0.9f * fk);
        box_rot(px2 + (s2 ? -0.32f : 0.32f), 176.9f, 0, 0, 0, 0.15f, 0.15f, 2.45f, 2.5f, blk, 0.0f);
    }
    box_rot(178.0f, 176.95f, 0, 0, 0, 1.75f, 0.05f, 2.45f, 3.05f, wood, 0.0f);
    box_rot(178.0f, 176.99f, 0, 0, 0, 1.7f, 0.02f, 2.47f, 2.51f, cyan, 0.8f);
    box_rot(178.0f, 176.99f, 0, 0, 0, 1.7f, 0.02f, 3.0f, 3.04f, cyan, 0.8f);
    box_rot(176.4f, 176.92f, 0, 0, 0, 0.03f, 0.03f, 3.05f, YE, blk, 0.0f);                // cadenas del letrero
    box_rot(179.6f, 176.92f, 0, 0, 0, 0.03f, 0.03f, 3.05f, YE, blk, 0.0f);
    static const char txt[7] = "ANTENA";
    for (int i = 0; i < 6; i++) {
        float e = 1.0f;
        if (i == 2 && sinf(t * 17.0f) + sinf(t * 5.3f) > 1.75f) e = 0.15f;
        neon_letter(txt[i], 178.0f - ((float)i - 2.5f) * 0.5f, 2.56f, cyan, e, 177.02f, 0.32f, 0.38f, 0.06f);
    }
    box_rot(178.0f, Z1 + 0.65f, 0, 0, 0, 1.8f, 0.55f, 0.0f, 0.12f, stone, 0.0f);
    box_rot(178.0f, Z1 + 1.35f, 0, 0, 0, 1.8f, 0.15f, 0.0f, 0.06f, stone, 0.0f);
    box_rot(178.0f, Z1 + 0.65f, 0, 0, 0, 0.9f, 0.4f, 0.12f, 0.15f, ebox, 0.0f);          // felpudo
    // chimenea de piedra y mastil de radio con luz roja
    box_rot(181.6f, 168.4f, 0, 0, 0, 0.42f, 0.42f, 4.4f, 6.5f, stone, 0.0f);
    box_rot(181.6f, 168.4f, 0, 0, 0, 0.55f, 0.55f, 6.5f, 6.68f, cab, 0.0f);
    box_rot(175.0f, 170.0f, 0, 0, 0, 0.07f, 0.07f, YR, 9.6f, cab, 0.0f);
    box_rot(175.0f, 170.0f, 0, 0, 0, 0.9f, 0.04f, 8.1f, 8.16f, cab, 0.0f);
    box_rot(175.0f, 170.0f, 0, 0, 0, 0.6f, 0.04f, 8.7f, 8.76f, cab, 0.0f);
    box_rot(175.0f, 170.0f, 0, 0, 0, 0.04f, 0.5f, 7.5f, 7.56f, cab, 0.0f);
    box_rot(175.0f, 170.0f, 0, 0, 0, 0.13f, 0.13f, 9.6f, 9.86f, redc, (sinf(t * 3.2f) > 0.2f) ? 1.0f : 0.15f);
    // lado este: caja electrica con rayo, equipo de aire en el suelo y canaleta hasta la torre
    box_rot(X1 + 0.14f, 172.6f, 0, 0, 0, 0.14f, 0.5f, 1.15f, 2.0f, ebox, 0.0f);
    box_rot(X1 + 0.29f, 172.6f, 0, 0, 0, 0.02f, 0.22f, 1.5f, 1.9f, yel, 0.0f);
    box_rot(X1 + 0.14f, 172.6f, 0, 0, 0, 0.04f, 0.04f, 0.2f, 1.15f, cab, 0.0f);
    box_rot(X1 + 1.5f, 167.2f, 0, 0, 0, 0.5f, 0.9f, 0.0f, 0.95f, ac, 0.0f);
    for (int k = 0; k < 5; k++) box_rot(X1 + 1.5f + 0.5f * 0.0f, 166.5f + 0.35f * (float)k, 0, 0, 0, 0.52f, 0.03f, 0.2f, 0.85f, cab, 0.0f);
    box_rot(187.1f, 172.6f, 0, 0, 0, 3.0f, 0.06f, 0.0f, 0.1f, cab, 0.0f);
    box_rot(190.1f, 175.3f, 0, 0, 0, 0.06f, 2.8f, 0.0f, 0.1f, cab, 0.0f);
    box_rot(191.3f, 178.0f, 0, 0, 0, 1.2f, 0.06f, 0.0f, 0.1f, cab, 0.0f);
    (void)woodl; (void)Z0;
}

// Refugio / centro de seguridad (celdas x 304..316, z 164..180; entrada al sur en x 308..312): paredes delgadas de concreto,
// techo a dos aguas con alero, porche con letrero REFUGIO, marco de acero, camara, cruz de primeros auxilios, ventanas,
// paneles solares y mastil de radio con baliza, luces de emergencia dentro.
static void draw_shelter(float t)
{
    if (cur_layer != 0 && !climbing) return;
    if (!in_view(310.0f, 172.0f, 13.0f, fminf(draw_lim, (gfx_pd[gfx] * rd_k)))) return;
    static const float conc[3] = { 168.f, 168.f, 160.f }, conc2[3] = { 120.f, 124.f, 124.f }, trim[3] = { 70.f, 76.f, 80.f }, steel[3] = { 96.f, 104.f, 112.f };
    static const float slate[3] = { 58.f, 66.f, 78.f }, grn[3] = { 70.f, 230.f, 140.f }, wht[3] = { 245.f, 245.f, 240.f }, blk[3] = { 26.f, 28.f, 30.f };
    static const float panel[3] = { 28.f, 48.f, 92.f }, glass[3] = { 38.f, 62.f, 84.f }, lampc[3] = { 255.f, 236.f, 190.f }, redc[3] = { 255.f, 40.f, 40.f };
    static const float pave[3] = { 112.f, 114.f, 110.f }, yel[3] = { 240.f, 196.f, 40.f };
    const float XL = 304.0f, XR = 316.0f, ZN = 164.0f, ZF = 176.0f, CX = 310.0f, WH = 3.4f;
    float ddx = px - CX, ddz = pz - 172.0f;
    int near_ = (ddx * ddx + ddz * ddz) < 40.0f * 40.0f;
    // paredes delgadas (la puerta ocupa el hueco central de la fachada, x 308..312)
    box_rot(XL, 170.0f, 0, 0, 0, 0.2f, 6.0f, 0.0f, WH, conc, 0.0f);
    box_rot(XR, 170.0f, 0, 0, 0, 0.2f, 6.0f, 0.0f, WH, conc, 0.0f);
    box_rot(CX, ZN, 0, 0, 0, 6.0f, 0.2f, 0.0f, WH, conc, 0.0f);
    box_rot(306.0f, ZF, 0, 0, 0, 2.0f, 0.2f, 0.0f, WH, conc, 0.0f);
    box_rot(314.0f, ZF, 0, 0, 0, 2.0f, 0.2f, 0.0f, WH, conc, 0.0f);
    // zocalo oscuro y esquinas
    box_rot(XL - 0.22f, 170.0f, 0, 0, 0, 0.04f, 6.2f, 0.0f, 0.5f, conc2, 0.0f);
    box_rot(XR + 0.22f, 170.0f, 0, 0, 0, 0.04f, 6.2f, 0.0f, 0.5f, conc2, 0.0f);
    box_rot(CX, ZN - 0.22f, 0, 0, 0, 6.2f, 0.04f, 0.0f, 0.5f, conc2, 0.0f);
    for (int a = 0; a < 2; a++)
        for (int b = 0; b < 2; b++) box_rot(a ? XR : XL, b ? ZF : ZN, 0, 0, 0, 0.3f, 0.3f, 0.0f, WH + 0.1f, conc2, 0.0f);
    // ventanas (marco claro + cristal): 3 por costado y 2 al fondo
    if (near_) {
        for (int s2 = 0; s2 < 2; s2++) {
            float z = s2 ? 173.0f : 167.0f, xo = XL - 0.23f;
            box_rot(xo, z, 0, 0, 0, 0.05f, 0.78f, 1.1f, 2.6f, wht, 0.0f);
            box_rot(xo - 0.03f, z, 0, 0, 0, 0.03f, 0.64f, 1.22f, 2.48f, glass, 0.25f);
        }
        for (int s2 = 0; s2 < 2; s2++) {
            float x = s2 ? 313.0f : 307.0f;
            box_rot(x, ZN - 0.23f, 0, 0, 0, 0.78f, 0.05f, 1.1f, 2.6f, wht, 0.0f);
            box_rot(x, ZN - 0.26f, 0, 0, 0, 0.64f, 0.03f, 1.22f, 2.48f, glass, 0.25f);
        }
    }
    // techo a dos aguas con la cumbrera hacia el frente
    roof_rot(CX, 171.6f, 0, 6.6f, 8.2f, 3.5f, 5.9f, slate);
    box_rot(CX, 171.6f, 0, 0, 0, 0.12f, 8.2f, 5.86f, 6.02f, trim, 0.0f);
    box_rot(CX, 179.78f, 0, 0, 0, 6.6f, 0.02f, 3.5f, 3.62f, trim, 0.0f);
    {   // frontal de concreto bajo el alero (triangulo)
        V a0 = mk(XL + 0.2f, 3.62f, 179.76f, conc, 0), b0 = mk(XR - 0.2f, 3.62f, 179.76f, conc, 0), c0 = mk(CX, 5.75f, 179.76f, conc, 0);
        tri_cam(a0, b0, c0);
    }
    // porche: losa, dos postes y viga
    box_rot(CX, 178.0f, 0, 0, 0, 6.2f, 2.2f, 0.0f, 0.15f, pave, 0.0f);
    for (int s2 = 0; s2 < 2; s2++) box_rot(s2 ? 315.4f : 304.6f, 179.2f, 0, 0, 0, 0.13f, 0.13f, 0.15f, WH + 0.1f, steel, 0.0f);
    box_rot(CX, 179.2f, 0, 0, 0, 5.9f, 0.14f, WH, WH + 0.2f, trim, 0.0f);
    box_rot(307.5f, 178.0f, 0, 0, 0, 0.3f, 0.08f, 3.3f, 3.4f, lampc, 0.8f);
    box_rot(312.5f, 178.0f, 0, 0, 0, 0.3f, 0.08f, 3.3f, 3.4f, lampc, 0.8f);
    // puerta: marco de acero, camara, cruz de primeros auxilios y lector
    box_rot(307.8f, ZF + 0.12f, 0, 0, 0, 0.18f, 0.3f, 0.0f, WH, steel, 0.0f);
    box_rot(312.2f, ZF + 0.12f, 0, 0, 0, 0.18f, 0.3f, 0.0f, WH, steel, 0.0f);
    box_rot(CX, ZF + 0.34f, 0, 0, 0, 2.0f, 0.02f, WH + 0.02f, WH + 0.1f, grn, 0.9f);
    box_rot(314.8f, 178.6f, 0, 0, 0, 0.18f, 0.18f, 2.9f, 3.25f, blk, 0.0f);
    box_rot(314.8f, 178.4f, 0, 0, 0, 0.05f, 0.05f, 3.1f, 3.17f, redc, (sinf(t * 4.0f) > 0.3f) ? 1.0f : 0.1f);
    box_rot(306.0f, ZF + 0.25f, 0, 0, 0, 0.5f, 0.03f, 1.5f, 2.7f, grn, 0.45f);
    box_rot(306.0f, ZF + 0.29f, 0, 0, 0, 0.35f, 0.02f, 1.95f, 2.25f, wht, 0.7f);
    box_rot(306.0f, ZF + 0.29f, 0, 0, 0, 0.1f, 0.02f, 1.65f, 2.55f, wht, 0.7f);
    box_rot(313.4f, ZF + 0.24f, 0, 0, 0, 0.18f, 0.03f, 1.2f, 1.8f, blk, 0.0f);
    box_rot(313.4f, ZF + 0.27f, 0, 0, 0, 0.07f, 0.02f, 1.55f, 1.65f, grn, 0.9f);
    // letrero REFUGIO en el frontal
    static const char txt[8] = "REFUGIO";
    for (int i = 0; i < 7; i++) {
        float e = 1.0f;
        if (i == 4 && sinf(t * 13.0f) + sinf(t * 4.7f) > 1.8f) e = 0.2f;
        neon_letter(txt[i], CX - ((float)i - 3.0f) * 0.62f, 3.95f, grn, e, 179.8f, 0.46f, 0.7f, 0.09f);
    }
    // paneles solares en la vertiente este, mastil con baliza
    if (near_) {
        for (int k = 0; k < 3; k++) {
            float z0 = 165.0f + 3.6f * (float)k, z1 = z0 + 3.2f;
            float xa = CX + 1.0f, xb = CX + 4.6f;
            float ya = 5.9f - (xa - CX) * (2.4f / 6.6f) + 0.07f, yb = 5.9f - (xb - CX) * (2.4f / 6.6f) + 0.07f;
            float q[4][3] = { { xa, ya, z0 }, { xb, yb, z0 }, { xb, yb, z1 }, { xa, ya, z1 } };
            quad_sub(q, panel, 2, 0.0f);
        }
    }
    box_rot(CX, 166.0f, 0, 0, 0, 0.07f, 0.07f, 5.9f, 9.3f, steel, 0.0f);
    box_rot(CX, 166.0f, 0, 0, 0, 0.8f, 0.04f, 8.0f, 8.06f, steel, 0.0f);
    box_rot(CX, 165.6f, 0, 0, 0, 0.5f, 0.07f, 7.0f, 7.7f, wht, 0.0f);
    box_rot(CX, 166.0f, 0, 0, 0, 0.13f, 0.13f, 9.3f, 9.56f, grn, 0.4f + 0.6f * (0.5f + 0.5f * sinf(t * 2.4f)));
    // bolardos al frente
    for (int s2 = 0; s2 < 2; s2++) {
        float x = s2 ? 313.2f : 306.8f;
        box_rot(x, 182.4f, 0, 0, 0, 0.14f, 0.14f, 0.0f, 0.9f, yel, 0.0f);
        box_rot(x, 182.4f, 0, 0, 0, 0.145f, 0.145f, 0.55f, 0.68f, blk, 0.0f);
    }
    // interior: luces de emergencia en el techo y cruz verde en el muro del fondo
    box_rot(307.0f, 170.0f, 0, 0, 0, 0.1f, 5.4f, 3.3f, 3.38f, lampc, 0.85f);
    box_rot(313.0f, 170.0f, 0, 0, 0, 0.1f, 5.4f, 3.3f, 3.38f, lampc, 0.85f);
    box_rot(CX, ZN + 0.24f, 0, 0, 0, 0.6f, 0.03f, 1.8f, 2.9f, grn, 0.5f);
    box_rot(CX, ZN + 0.27f, 0, 0, 0, 0.4f, 0.02f, 2.15f, 2.55f, wht, 0.7f);
    box_rot(CX, ZN + 0.27f, 0, 0, 0, 0.12f, 0.02f, 1.95f, 2.75f, wht, 0.7f);
    // decoracion: mesa central (ahi queda la llave), camas de refugiados en el suelo y varias con sangre
    {
        static const float wood[3] = { 96.f, 70.f, 46.f }, lant[3] = { 255.f, 200.f, 120.f };
        box_rot(CX, 170.0f, 0, 0, 0, 1.0f, 0.6f, 0.74f, 0.8f, wood, 0.0f);
        for (int a = 0; a < 4; a++) box_rot(CX + ((a & 1) ? 0.9f : -0.9f), 170.0f + ((a & 2) ? 0.5f : -0.5f), 0, 0, 0, 0.05f, 0.05f, 0.0f, 0.74f, wood, 0.0f);
        box_rot(CX - 0.7f, 170.0f, 0, 0, 0, 0.09f, 0.09f, 0.8f, 0.98f, lant, 0.9f);
        if (near_ || (ddx * ddx + ddz * ddz) < 26.0f * 26.0f) {
            static const float bed[8][4] = {      // x, z, giro, sangre (0 limpia, 1 manchada, 2 llena de sangre)
                { 313.1f, 165.5f, 0.0f, 0.0f }, { 311.5f, 165.5f, 0.0f, 1.0f }, { 308.5f, 165.5f, 0.0f, 2.0f }, { 306.9f, 165.5f, 0.0f, 0.0f },
                { 305.3f, 167.6f, 1.571f, 0.0f }, { 305.3f, 173.2f, 1.571f, 2.0f }, { 314.1f, 170.0f, 1.571f, 1.0f }, { 313.6f, 173.9f, 0.0f, 0.0f } };
            static const float mat[3][3] = { { 150.f, 140.f, 115.f }, { 120.f, 126.f, 120.f }, { 138.f, 128.f, 104.f } };
            static const float blk2[3][3] = { { 70.f, 86.f, 60.f }, { 96.f, 80.f, 62.f }, { 74.f, 76.f, 96.f } };
            static const float pil[3] = { 200.f, 200.f, 190.f }, bl[3] = { 104.f, 8.f, 8.f }, bl2[3] = { 78.f, 6.f, 6.f };
            for (int b = 0; b < 8; b++) {
                float bx = bed[b][0], bz = bed[b][1], ba = bed[b][2];
                int bd = (int)bed[b][3];
                box_rot(bx, bz, ba, 0, 0, 0.45f, 1.0f, 0.03f, 0.2f, mat[b % 3], 0.0f);
                box_rot(bx, bz, ba, 0, 0.4f, 0.47f, 0.6f, 0.2f, 0.26f, blk2[(b + 1) % 3], 0.0f);
                box_rot(bx, bz, ba, 0, -0.75f, 0.3f, 0.2f, 0.2f, 0.3f, pil, 0.0f);
                if (bd >= 1) box_rot(bx, bz, ba, 0.05f, 0.25f, 0.28f, 0.3f, 0.262f, 0.272f, bl, 0.0f);
                if (bd >= 2) {
                    box_rot(bx, bz, ba, -0.1f, 0.75f, 0.32f, 0.2f, 0.262f, 0.272f, bl2, 0.0f);
                    box_rot(bx, bz, ba, 0.0f, -0.7f, 0.2f, 0.14f, 0.3f, 0.31f, bl, 0.0f);
                    box_rot(bx, bz, ba, 0.62f, 0.2f, 0.18f, 0.5f, 0.0f, 0.012f, bl2, 0.0f);
                    box_rot(bx, bz, ba, 0.7f, 0.95f, 0.1f, 0.12f, 0.0f, 0.012f, bl, 0.0f);
                }
            }
            box_rot(310.8f, 174.9f, 0, 0, 0, 0.3f, 0.22f, 0.012f, 0.014f, bl2, 0.0f);       // charcos en el suelo
            box_rot(307.6f, 168.2f, 0.3f, 0, 0, 0.22f, 0.16f, 0.012f, 0.014f, bl, 0.0f);
        }
    }
}

// Granero (establo de ladrillo): paredes delgadas rojas con molduras blancas, techo de granero (mansarda) con ventana del
// henil, cupula con veleta, faroles, pacas. Cuarto de x 316..332, z 300..324; puerta doble al sur (x 320..328).
// Y el letrero "BIENVENIDO" (de madera, sin neon) sobre el camino, antes de llegar.
static void draw_barn(float t)
{
    if (cur_layer != 0 && !climbing) return;
    const float lim = fminf(draw_lim, (gfx_pd[gfx] * rd_k));
    static const float woodD[3] = { 70.f, 46.f, 28.f }, board[3] = { 98.f, 64.f, 36.f }, cream[3] = { 242.f, 232.f, 200.f };
    if (in_view(324.0f, 342.0f, 7.0f, lim)) {
        for (int s2 = 0; s2 < 2; s2++) box_rot(s2 ? 328.6f : 319.4f, 342.0f, 0, 0, 0, 0.22f, 0.22f, 0.0f, 4.7f, woodD, 0.0f);
        box_rot(324.0f, 342.0f, 0, 0, 0, 4.7f, 0.14f, 3.3f, 4.5f, board, 0.0f);
        box_rot(324.0f, 342.0f, 0, 0, 0, 4.85f, 0.18f, 4.5f, 4.7f, woodD, 0.0f);
        box_rot(324.0f, 342.0f, 0, 0, 0, 4.85f, 0.18f, 3.1f, 3.3f, woodD, 0.0f);
        static const char hi[11] = "BIENVENIDO";
        for (int i = 0; i < 10; i++)
            neon_letter_now(hi[i], 324.0f - ((float)i - 4.5f) * 0.82f, 3.55f, cream, 0.0f, 342.15f, 0.6f, 0.7f, 0.1f);
    }
    if (!in_view(324.0f, 312.0f, 20.0f, lim)) return;
    static const float red[3] = { 156.f, 42.f, 36.f }, redD[3] = { 120.f, 32.f, 28.f }, white[3] = { 238.f, 234.f, 226.f }, stone[3] = { 128.f, 126.f, 122.f };
    static const float roof[3] = { 64.f, 60.f, 64.f }, dark[3] = { 28.f, 24.f, 24.f }, glass[3] = { 44.f, 52.f, 66.f }, lant[3] = { 255.f, 200.f, 120.f };
    static const float hay[3] = { 205.f, 170.f, 70.f }, hay2[3] = { 190.f, 154.f, 60.f };
    const float XL = 316.0f, XR = 332.0f, ZN = 300.0f, ZS = 324.0f, CX = 324.0f, WH = 5.5f;
    float ddx = px - CX, ddz = pz - 312.0f;
    int near_ = (ddx * ddx + ddz * ddz) < 45.0f * 45.0f;
    // paredes delgadas (el hueco x 320..328 es la puerta doble)
    box_rot(XL, 312.0f, 0, 0, 0, 0.2f, 12.0f, 0.0f, WH, red, 0.0f);
    box_rot(XR, 312.0f, 0, 0, 0, 0.2f, 12.0f, 0.0f, WH, red, 0.0f);
    box_rot(CX, ZN, 0, 0, 0, 8.0f, 0.2f, 0.0f, WH, red, 0.0f);
    box_rot(318.0f, ZS, 0, 0, 0, 2.0f, 0.2f, 0.0f, WH, red, 0.0f);
    box_rot(330.0f, ZS, 0, 0, 0, 2.0f, 0.2f, 0.0f, WH, red, 0.0f);
    // base de piedra y esquinas blancas
    box_rot(XL - 0.22f, 312.0f, 0, 0, 0, 0.04f, 12.2f, 0.0f, 0.6f, stone, 0.0f);
    box_rot(XR + 0.22f, 312.0f, 0, 0, 0, 0.04f, 12.2f, 0.0f, 0.6f, stone, 0.0f);
    box_rot(CX, ZN - 0.22f, 0, 0, 0, 8.2f, 0.04f, 0.0f, 0.6f, stone, 0.0f);
    box_rot(318.0f, ZS + 0.22f, 0, 0, 0, 2.2f, 0.04f, 0.0f, 0.6f, stone, 0.0f);
    box_rot(330.0f, ZS + 0.22f, 0, 0, 0, 2.2f, 0.04f, 0.0f, 0.6f, stone, 0.0f);
    for (int a = 0; a < 2; a++)
        for (int b = 0; b < 2; b++) box_rot(a ? XR : XL, b ? ZS : ZN, 0, 0, 0, 0.28f, 0.28f, 0.0f, WH + 0.05f, white, 0.0f);
    // marco blanco de la puerta doble y riel
    box_rot(319.7f, ZS + 0.05f, 0, 0, 0, 0.24f, 0.3f, 0.0f, WH + 0.35f, white, 0.0f);
    box_rot(328.3f, ZS + 0.05f, 0, 0, 0, 0.24f, 0.3f, 0.0f, WH + 0.35f, white, 0.0f);
    box_rot(CX, ZS + 0.05f, 0, 0, 0, 4.55f, 0.3f, WH, WH + 0.35f, white, 0.0f);
    // techo de granero (mansarda): dos pendientes por lado
    {
        const float z0 = 299.2f, z1 = 324.8f, ex = 8.6f, kx = 6.0f;
        float q1[4][3] = { { CX - ex, WH, z0 }, { CX - ex, WH, z1 }, { CX - kx, 8.0f, z1 }, { CX - kx, 8.0f, z0 } };
        float q2[4][3] = { { CX - kx, 8.0f, z0 }, { CX - kx, 8.0f, z1 }, { CX, 9.5f, z1 }, { CX, 9.5f, z0 } };
        float q3[4][3] = { { CX + ex, WH, z0 }, { CX + ex, WH, z1 }, { CX + kx, 8.0f, z1 }, { CX + kx, 8.0f, z0 } };
        float q4[4][3] = { { CX + kx, 8.0f, z0 }, { CX + kx, 8.0f, z1 }, { CX, 9.5f, z1 }, { CX, 9.5f, z0 } };
        quad_sub(q1, roof, 3, 0.0f); quad_sub(q2, roof, 3, 0.0f); quad_sub(q3, roof, 3, 0.0f); quad_sub(q4, roof, 3, 0.0f);
        for (int e = 0; e < 2; e++) {                               // frontales (pentagono): rojo
            float zz = e ? z1 - 0.02f : z0 + 0.02f;
            V a = mk(CX - ex, WH, zz, red, 0), b = mk(CX + ex, WH, zz, red, 0), c = mk(CX + kx, 8.0f, zz, red, 0), d = mk(CX, 9.5f, zz, red, 0), f = mk(CX - kx, 8.0f, zz, red, 0);
            tri_cam(a, b, c); tri_cam(a, c, d); tri_cam(a, d, f);
        }
        box_rot(CX, 312.0f, 0, 0, 0, 0.12f, 12.8f, 9.45f, 9.6f, white, 0.0f);          // cumbrera
        box_rot(CX - kx, 312.0f, 0, 0, 0, 0.09f, 12.8f, 7.95f, 8.08f, white, 0.0f);      // quiebre de la mansarda
        box_rot(CX + kx, 312.0f, 0, 0, 0, 0.09f, 12.8f, 7.95f, 8.08f, white, 0.0f);
        // ventana del henil con marco blanco, y la viga del gancho
        box_rot(CX, z1 + 0.0f, 0, 0, 0, 1.5f, 0.05f, 6.0f, 8.3f, white, 0.0f);
        box_rot(CX, z1 + 0.04f, 0, 0, 0, 1.25f, 0.03f, 6.25f, 8.05f, dark, 0.0f);
        box_rot(CX, z1 + 0.07f, 0, 0, 0, 0.05f, 0.03f, 6.25f, 8.05f, white, 0.0f);
        box_rot(CX, z1 + 0.07f, 0, 0, 0, 1.25f, 0.03f, 7.1f, 7.18f, white, 0.0f);
        box_rot(CX, z1 + 0.9f, 0, 0, 0, 0.08f, 0.9f, 9.0f, 9.14f, white, 0.0f);
    }
    // cupula de ventilacion con veleta
    box_rot(CX, 312.0f, 0, 0, 0, 0.95f, 0.95f, 9.4f, 10.5f, red, 0.0f);
    box_rot(CX, 312.0f, 0, 0, 0, 1.0f, 1.0f, 10.4f, 10.5f, white, 0.0f);
    pyr_rot(CX, 312.0f, 1.25f, 10.5f, 11.7f, roof);
    box_rot(CX, 312.0f, 0, 0, 0, 0.03f, 0.03f, 11.7f, 12.9f, dark, 0.0f);
    box_rot(CX, 312.0f, 0, 0, 0.5f, 0.03f, 0.5f, 12.2f, 12.3f, dark, 0.0f);
    // ventanas laterales (tres por lado) y faroles junto a la puerta
    if (near_) {
        for (int s2 = 0; s2 < 6; s2++) {
            float z = 305.0f + 7.0f * (float)(s2 % 3), xo = (s2 >= 3) ? XR + 0.23f : XL - 0.23f;
            box_rot(xo, z, 0, 0, 0, 0.05f, 0.95f, 2.3f, 4.0f, white, 0.0f);
            box_rot(xo + ((s2 >= 3) ? 0.03f : -0.03f), z, 0, 0, 0, 0.03f, 0.8f, 2.45f, 3.85f, glass, 0.15f);
            box_rot(xo + ((s2 >= 3) ? 0.05f : -0.05f), z, 0, 0, 0, 0.02f, 0.03f, 2.45f, 3.85f, white, 0.0f);
        }
        for (int s2 = 0; s2 < 2; s2++) {
            float x = s2 ? 329.2f : 318.8f;
            box_rot(x, 325.2f, 0, 0, 0, 0.06f, 0.06f, 0.0f, 2.6f, dark, 0.0f);
            box_rot(x, 325.2f, 0, 0, 0, 0.14f, 0.14f, 2.6f, 3.0f, lant, 0.9f);
            box_rot(x, 325.2f, 0, 0, 0, 0.2f, 0.2f, 3.0f, 3.06f, dark, 0.0f);
        }
        // pacas de heno junto a la entrada
        box_rot(317.4f, 327.2f, 0, 0, 0, 0.95f, 0.5f, 0.0f, 0.6f, hay, 0.0f);
        box_rot(317.4f, 327.2f, 0, 0, 0, 0.85f, 0.45f, 0.6f, 1.2f, hay2, 0.0f);
        box_rot(330.8f, 327.0f, 0, 0, 0, 0.95f, 0.5f, 0.0f, 0.6f, hay2, 0.0f);
    }
}

static void draw_church(void)
{
    if (cur_layer != 0 && !climbing) return;
    float lim = fminf(draw_lim, (gfx_pd[gfx] * rd_k));
    if (!in_view(58.0f, 64.0f, 30.0f, lim)) return;
    static const float cc[8][3] = { { 225.f, 218.f, 200.f }, { 130.f, 60.f, 46.f }, { 90.f, 150.f, 130.f }, { 50.f, 50.f, 56.f },
                                    { 150.f, 190.f, 230.f }, { 190.f, 185.f, 170.f }, { 110.f, 150.f, 220.f }, { 80.f, 52.f, 30.f } };
    static V vv[CH_NV];
    static const float white[3] = { 1.0f, 1.0f, 1.0f };
    const float S = 0.05f, X0 = 58.0f, Z0 = 67.75f;
    for (int i = 0; i < CH_NV; i++)
        vv[i] = mk(X0 + (float)ch_v[i][0] * S, (float)ch_v[i][1] * S, Z0 + (float)ch_v[i][2] * S, white, 0.0f);
    for (int k = 0; k < CH_NT; k++) {
        const unsigned short *t = ch_t[k];
        const float *c = cc[t[3]];
        float sh = (float)t[4] / 255.0f;
        V v[3];
        for (int j = 0; j < 3; j++) {
            v[j] = vv[t[j]];
            v[j].r *= c[0] * sh; v[j].g *= c[1] * sh; v[j].b *= c[2] * sh;
        }
        tri_cam(v[0], v[1], v[2]);
    }
}

