static const short *dance_tab[4] = { flair_dat, breakdance_dat, twerk_dat, gangnam_dat };
static const int dance_frames[4] = { 60, 30, 455, 296 };
static const float dance_fps[4] = { 60.0f, 60.0f, 30.0f, 24.0f };      // cuadros por segundo de cada baile
typedef struct { StCtx C; StPart legA, legB, body, head, armL, armR; } StPose;

static void st_pose(const Player *Q, StPose *S)
{
    float cf = Q->crouch_f, ys = 1.0f - 0.4f * cf, drop = 1.2f * cf;
    float sw = sinf(Q->walk_ph) * Q->walk_amp;
    float sy = sinf(Q->yaw), cy = cosf(Q->yaw);
    S->C.x = Q->px; S->C.z = Q->pz; S->C.fy = Q->foot_y + Q->jump_h;
    S->C.fwx = sy; S->C.fwz = cy; S->C.rtx = cy; S->C.rtz = -sy;
    S->legA = (StPart){ 3.5f,  sw * 0.9f, ys, drop };
    S->legB = (StPart){ 3.5f, -sw * 0.9f, ys, drop };
    S->body = (StPart){ 6.49f, 0.0f, 1.0f, drop };
    S->head = (StPart){ 6.49f, clampf(Q->pitch * 0.8f, -0.7f, 0.7f), 1.0f, drop };
    S->armL = (StPart){ 6.2f, -sw * 0.8f, 1.0f, drop };
    S->armR = (StPart){ 6.2f, 1.30f + clampf(Q->pitch, -0.9f, 0.9f) * 0.6f, 1.0f, drop };   // linterna al frente
    StPart *ps[6] = { &S->legA, &S->legB, &S->body, &S->head, &S->armL, &S->armR };
    if (Q->dance_id >= 0 && state == 0 && !Q->climbing) {            // BAILES (animacion importada, cuadro a cuadro a 60 por segundo)
        int di = Q->dance_id < 4 ? Q->dance_id : 0;
        float fpos = Q->dance_t * dance_fps[di];
        int i0 = (int)fpos, nfr = dance_frames[di]; float fa = fpos - (float)i0;
        i0 %= nfr; int i1 = (i0 + 1) % nfr;
        const short *d0 = dance_tab[di] + i0 * 66, *d1 = dance_tab[di] + i1 * 66;
        short dl[66];
        for (int j = 0; j < 66; j++) dl[j] = (short)(d0[j] + (int)((d1[j] - d0[j]) * fa));      // mezcla entre cuadros
        const short *d = dl;
        float H[3] = { d[0] / 4096.0f, d[1] / 4096.0f, d[2] / 4096.0f }, R[7][9];
        for (int k = 0; k < 7; k++) for (int j = 0; j < 9; j++) R[k][j] = d[3 + k * 9 + j] / 16384.0f;
        #define RV(k, x, y, z, o) { o[0] = R[k][0] * (x) + R[k][1] * (y) + R[k][2] * (z); o[1] = R[k][3] * (x) + R[k][4] * (y) + R[k][5] * (z); o[2] = R[k][6] * (x) + R[k][7] * (y) + R[k][8] * (z); }
        float o[3];
        // 0 cuerpo, 1 cadera, 2 cabeza, 3 brazo izq, 4 brazo der, 5 pierna izq, 6 pierna der
        StPart *pp[7] = { &S->body, 0, &S->head, &S->armL, &S->armR, &S->legA, &S->legB };
        float pv[7] = { 3.5f, 0, 6.49f, 6.2f, 6.2f, 3.5f, 3.5f }, pzz[7] = { 0, 0, 0, -1.745f, 1.745f, -0.57f, 0.57f };
        for (int k = 0; k < 7; k++) {
            if (!pp[k]) continue;
            StPart *q = pp[k];
            q->full = 1; q->py = pv[k]; q->pz = pzz[k];
            for (int j = 0; j < 9; j++) q->R[j] = R[k][j];
            if (k == 0) { q->tx = H[0]; q->ty = H[1]; q->tz = H[2]; }
            else if (k == 2) { RV(0, 0.0f, 2.99f, 0.0f, o); q->tx = H[0] + o[0]; q->ty = H[1] + o[1]; q->tz = H[2] + o[2]; }
            else if (k == 3 || k == 4) { RV(0, 0.0f, 2.7f, pzz[k], o); q->tx = H[0] + o[0]; q->ty = H[1] + o[1]; q->tz = H[2] + o[2]; }
            else { RV(1, 0.0f, 0.0f, pzz[k], o); q->tx = H[0] + o[0]; q->ty = H[1] + o[1]; q->tz = H[2] + o[2]; }
        }
        #undef RV
    }
    if (state == 0 && !Q->climbing && Q >= &P[0] && Q <= &P[MAXP - 1] && pl_dn[Q - P]) {      // CAIDO: boca abajo, arrastrandose con los brazos
        const float sw = sinf(Q->walk_ph) * (0.12f + 0.9f * Q->walk_amp);
        const float Tx = -1.0f, Ty = 1.7f;                         // cuerpo tendido: la barriga toca el piso
        const float pv[6] = { 3.5f, 3.5f, 3.5f, 6.49f, 6.2f, 6.2f };          // legA, legB, body, head, armL, armR (pivotes)
        const float pzv[6] = { -0.57f, 0.57f, 0.0f, 0.0f, -1.745f, 1.745f };
        float th[6];                                                // angulo de cada pieza
        th[0] = 0.18f * sw; th[1] = -0.18f * sw; th[2] = 0.0f; th[3] = 0.0f;
        th[4] = 3.14159f + (-0.25f + 0.55f * sw);                   // brazos hacia adelante, uno y otro alternados
        th[5] = 3.14159f + (-0.25f - 0.55f * sw);
        for (int k = 0; k < 6; k++) {
            StPart *q = ps[k];
            float c = cosf(th[k]), s_ = sinf(th[k]);
            q->full = 1; q->py = pv[k]; q->pz = pzv[k];
            // R = Rg * Rz(th): modelo tumbado hacia adelante
            q->R[0] = s_; q->R[1] = c;  q->R[2] = 0.0f;
            q->R[3] = -c; q->R[4] = s_; q->R[5] = 0.0f;
            q->R[6] = 0.0f; q->R[7] = 0.0f; q->R[8] = 1.0f;
            q->tx = Tx + (pv[k] - 3.5f); q->ty = Ty; q->tz = pzv[k];
        }
        {   // cabeza levantada mirando al frente
            StPart *q = &S->head;
            const float phi = 0.9f, c = cosf(phi), s_ = sinf(phi);
            q->R[0] = s_; q->R[1] = c;  q->R[2] = 0.0f;
            q->R[3] = -c; q->R[4] = s_; q->R[5] = 0.0f;
            q->R[6] = 0.0f; q->R[7] = 0.0f; q->R[8] = 1.0f;
        }
    }
    for (int i = 0; i < 6; i++) if (!ps[i]->full) { ps[i]->c = cosf(ps[i]->ang); ps[i]->s = sinf(ps[i]->ang); }   // una sola vez por parte
}

// Con varios jugadores solo hay UNA luz extra: la del otro jugador mas cercano con la linterna encendida (-1 = ninguna)
static int oth_idx = -1;
static int pick_other_light(void)
{
    int bi = -1; float bd = 1e18f;
    for (int o = 0; o < num_players; o++) {
        if (o == pl_cur) continue;
        const Player *Q = &P[o];
        if (!Q->flash_on || !(Q->cur_layer == cur_layer || Q->climbing || climbing)) continue;
        float dx = Q->px - px, dz = Q->pz - pz, d = dx * dx + dz * dz;
        if (d < bd) { bd = d; bi = o; }
    }
    return bi;
}

// Donde esta el lente de la linterna del otro jugador (para su brillo)
static int other_lens_world(float *wx, float *wy, float *wz)
{
    if (num_players < 2 || state != 0 || oth_idx < 0) return 0;
    const Player *Q = &P[oth_idx];
    if (!Q->flash_on || !(Q->cur_layer == cur_layer || Q->climbing || climbing)) return 0;
    StPose S; float o[3];
    st_pose(Q, &S);
    st_pt(&S.C, &S.armR, 0.0f, 2.2f, 1.75f, o);
    *wx = o[0]; *wy = o[1]; *wz = o[2];
    return 1;
}

