#define KB_CEN_Y 4.493f
static void kb_mesh(const StCtx *C, const StPart *p, const short *v, const signed char *n, const unsigned char *t,
                    int nv, int nt, const float *col, float emit)
{
    float d[160]; V vv[160];
    for (int i = 0; i < nv; i++) {
        float m[3], nx, ny, nz;
        st_pt(C, p, v[i * 3] * (1.0f / 256.0f), v[i * 3 + 1] * (1.0f / 256.0f), v[i * 3 + 2] * (1.0f / 256.0f), m);
        st_nrm(p, n[i * 3] * (1.0f / 120.0f), n[i * 3 + 1] * (1.0f / 120.0f), n[i * 3 + 2] * (1.0f / 120.0f), &nx, &ny, &nz);
        float wx = nx * C->fwx + nz * C->rtx, wz = nx * C->fwz + nz * C->rtz;
        d[i] = wx * (px - m[0]) + ny * (cam_y - m[1]) + wz * (pz - m[2]);
        float sh = 0.70f + 0.30f * ny; if (sh < 0.45f) sh = 0.45f;
        float c3[3] = { col[0] * sh, col[1] * sh, col[2] * sh };
        vv[i] = mk(m[0], m[1], m[2], c3, emit);
    }
    for (int k = 0; k < nt; k++) {
        int a = t[k * 3], b = t[k * 3 + 1], c = t[k * 3 + 2];
        if (d[a] < 0.0f && d[b] < 0.0f && d[c] < 0.0f) continue;
        tri_cam(vv[a], vv[b], vv[c]);
    }
}

// La cara (textura 64x64 del .obj) como rectangulos de color pegados al cuerpo segun las UV
static void kb_decals(const StCtx *C, const StPart *p, float emit)
{
    for (int r = 0; r < KB_NRUNS; r++) {
        const unsigned char *q = &kb_runs[r * 7];
        int gy0 = q[0], gy1 = gy0 + q[6], gx0 = q[1], gx1 = q[2];
        const int GX[4] = { gx0, gx1, gx1, gx0 }, GY[4] = { gy0, gy0, gy1, gy1 };
        float w[4][3], nyAvg = 0.0f; int front = 0;
        for (int k = 0; k < 4; k++) {
            const short *g = &kb_grid[(GY[k] * KB_GW + GX[k]) * 3];
            float x = g[0] * (1.0f / 256.0f), y = g[1] * (1.0f / 256.0f), z = g[2] * (1.0f / 256.0f);
            float ry = y - KB_CEN_Y, il = 1.0f / sqrtf(x * x + ry * ry + z * z);
            float n0 = x * il, n1 = ry * il, n2 = z * il;
            st_pt(C, p, x + n0 * 0.05f, y + n1 * 0.05f, z + n2 * 0.05f, w[k]);
            float nx, ny, nz; st_nrm(p, n0, n1, n2, &nx, &ny, &nz);
            float wx = nx * C->fwx + nz * C->rtx, wz = nx * C->fwz + nz * C->rtz;
            if (wx * (px - w[k][0]) + ny * (cam_y - w[k][1]) + wz * (pz - w[k][2]) > 0.0f) front++;
            nyAvg += ny;
        }
        if (!front) continue;
        float sh = 0.70f + 0.075f * nyAvg; if (sh < 0.45f) sh = 0.45f;
        float col[3] = { q[3] * sh, q[4] * sh, q[5] * sh };
        quad_sub(w, col, 1, emit);
    }
}

static void kirby_draw(const Player *Q, const StPose *S, float em)
{
    const StCtx *C = &S->C;
    static const float pink[3] = { 246.f, 164.f, 180.f }, red[3] = { 235.f, 22.f, 32.f };
    static const float dark[3] = { 38.f, 38.f, 42.f };
    float lens[3] = { 255.f, 246.f, 200.f };
    if (Q->uv_on) { lens[0] = 190.f; lens[1] = 110.f; lens[2] = 255.f; }
    if (!Q->flash_on) { lens[0] = 90.f; lens[1] = 90.f; lens[2] = 92.f; }
    float ddx = Q->px - px, ddz = Q->pz - pz, dd = ddx * ddx + ddz * ddz;
    kb_mesh(C, &S->legA, km_FOOTA_v, km_FOOTA_n, km_FOOTA_t, KM_FOOTA_NV, KM_FOOTA_NT, red, em);
    kb_mesh(C, &S->legB, km_FOOTB_v, km_FOOTB_n, km_FOOTB_t, KM_FOOTB_NV, KM_FOOTB_NT, red, em);
    kb_mesh(C, &S->body, km_BODY_v, km_BODY_n, km_BODY_t, KM_BODY_NV, KM_BODY_NT, pink, em);
    st_box(C, &S->body, -0.20f, 0.90f, 3.55f, 4.25f, 3.90f, 4.50f, dark, em);           // linterna en la mano derecha
    st_box(C, &S->body,  0.90f, 1.08f, 3.48f, 4.32f, 3.84f, 4.56f, lens, (Q->flash_on ? 0.85f : 0.05f));
    if (dd < 625.0f) kb_decals(C, &S->body, em);
}

