// llamas animadas de las velas (spritesheet horneado a 10x18 celdas, hoja de llama nueva)
static void draw_candle_flames(float t)
{
    if (cur_layer != 0 || climbing) return;
    int outside_ = 0;                                        // camara fuera de la iglesia: las llamas solo se ven a traves de la puerta abierta
    {   int cam_in = (px > 48.3f && px < 67.7f && pz > 56.4f && pz < 79.0f);
        if (!cam_in) {
            if (!in_view(58.0f, 57.0f, 6.0f, fminf(draw_lim, (gfx_pd[gfx] * rd_k)))) return;
            if (fabsf(px - 58.0f) > 40.0f || fabsf(pz - 62.0f) > 40.0f) return;   // la camara (no el personaje observado)
            if (pz <= 79.0f || !door_open[3]) return;                               // por detras o por los lados la pared las tapa; con la puerta cerrada tambien
            outside_ = 1;
        } }
    static const float cxs[4] = { 56.5f, 57.2f, 58.8f, 59.5f };
    for (int n = 0; n < 4; n++) {
        float fl = 0.75f + 0.25f * sinf(t * 13.0f + (float)n * 2.1f) + 0.1f * sinf(t * 31.0f + (float)n);
        draw_glow(cxs[n], 1.72f, 57.1f, 0.30f, 255, 190, 100, (int)(34.0f * fl));
        float dx = cxs[n] - px, dz = 57.1f - pz;
        float cxv = dx * rx + dz * rz, cz0 = dx * fx + dz * fz;
        float yb = 1.60f - cam_y, yt = 1.78f - cam_y;
        float cyb = yb * cpitch - cz0 * spitch, cyt = yt * cpitch - cz0 * spitch, czv = yb * spitch + cz0 * cpitch;
        if (czv < 0.4f) continue;
        if (outside_) {                                             // el rayo camara -> vela debe pasar por el hueco de la puerta (x 55.8..60.2 en la pared z 79)
            float tt = (pz - 79.0f) / (pz - 57.1f), xi = px + (cxs[n] - px) * tt;
            if (fabsf(xi - 58.0f) > 2.2f) continue;
        }
        float sx = W * 0.5f + cxv / czv * FOCAL;
        float syb = H * 0.5f - cyb / czv * FOCAL, syt = H * 0.5f - cyt / czv * FOCAL;
        float hpx = syb - syt;                       // alto de la llama en pantalla
        if (sx < -40.0f || sx > W + 40.0f) continue;
        if (hpx < 11.0f) { hpx = 11.0f; syt = syb - hpx; }   // tamano minimo en pantalla: la llama se sigue viendo a distancia
        float cw = hpx * 0.56f / FL_W, ch = hpx / FL_H;
        int fi = ((int)(t * 14.0f) + n * 7) % FL_N;
        int fz_ = spec_day ? glow_z(czv, 1.2f) : 16777100;   // de noche la oscuridad de pantalla (z 16777000) tapaba la llama: se dibuja por encima de ella; la linea de vista ya evita verla a traves de paredes
        for (int j = 0; j < FL_H; j++)
            for (int i = 0; i < FL_W; i++) {
                const unsigned char *c = fl_px[fi][j * FL_W + i];
                if (c[3] < 10) continue;
                float x = sx + ((float)i - FL_W * 0.5f) * cw, y = syt + (float)j * ch;
                gsKit_prim_sprite(gsGlobal, x, y, x + cw + 0.6f, y + ch + 0.6f, fz_, GS_SETREG_RGBAQ(c[0], c[1], c[2], ba((int)c[3]), 0x00));
            }
    }
}

static void draw_glows(float t)
{
    {   // linterna del otro jugador (se ve de lejos)
        float lx, ly, lz;
        if (other_lens_world(&lx, &ly, &lz) && los_to(lx, lz, 0.0f)) {
            if (oth_idx >= 0 && P[oth_idx].uv_on) draw_glow(lx, ly, lz, 0.20f, 180, 100, 255, 105);
            else draw_glow(lx, ly, lz, 0.20f, 255, 240, 190, 105);
        }
    }
    for (int i = 0; i < NIT; i++) {                         // llaves de color y papeles con codigo
        if (item_got[i] || cur_layer != 0) continue;
        float ix = items[i].x - px, iz = items[i].z - pz;
        if (ix * ix + iz * iz > 36.0f * 36.0f || !los_to(items[i].x, items[i].z, 0.0f)) continue;
        if (items[i].kind == 0) continue;                 // las llaves no brillan
        draw_glow(items[i].x, 0.12f + tab_h(items[i].x, items[i].z), items[i].z, 0.22f, 240, 240, 230, 95);
    }
    int got = notes_got[0] + notes_got[1] + notes_got[2];
    for (int i = 0; i < 3; i++) {
        if (notes_off[i] || (int)notes_pos[i][3] != cur_layer) continue;
    }
    // Luces del mundo (antena, ventanas, velas...)
    for (int i = 0; i < NBC; i++) {
        const Beacon *b = &beacons[i];
        if (b->layer != cur_layer) continue;
        if (b->z > 57.0f && b->z < 57.2f && b->x > 56.0f && b->x < 60.0f && !(fabsf(px - 58.0f) <= 40.0f && fabsf(pz - 62.0f) <= 40.0f)) continue;
        float dx = b->x - px, dz = b->z - pz;
        { float rg_ = b->range < GLOW_MAX ? b->range : GLOW_MAX; if (dx * dx + dz * dz > rg_ * rg_) continue; }
        if (b->period > 0.0f && fmodf(t + b->x * 0.37f, b->period) > b->period * 0.18f) continue;
        if (b->los && !los_to(b->x, b->z, 0.6f)) continue;
        draw_glow(b->x, b->y, b->z, b->rad, b->r, b->g, b->b, b->ac);
    }
    draw_candle_flames(t);
}

// ---------------- IA del monstruo (BFS) ----------------
static void compute_flow(int layer, int tx, int tz)
{
    int h = 0, t = 0;
    for (int z = 0; z < MH; z++) for (int x = 0; x < MW; x++) dist_map[z][x] = 9999;
    if (tx < 0 || tz < 0 || tx >= MW || tz >= MH) return;
    dist_map[tz][tx] = 0; bqx[t] = (short)tx; bqz[t++] = (short)tz;
    static const int dx[4] = {1, -1, 0, 0}, dz[4] = {0, 0, 1, -1};
    while (h < t) {
        int x = bqx[h], z = bqz[h++];
        for (int k = 0; k < 4; k++) {
            int nx = x + dx[k], nz = z + dz[k];
            if (nx < 0 || nz < 0 || nx >= MW || nz >= MH) continue;
            if (AI_SOLID(layer, nz, nx) || dist_map[nz][nx] != 9999) continue;
            dist_map[nz][nx] = dist_map[z][x] + 1;
            bqx[t] = (short)nx; bqz[t++] = (short)nz;
        }
    }
}

// camino recto libre (sin muros) entre dos puntos: el monstruo corta camino en vez de ir de celda en celda
static int mon_clear(int layer, float x0, float z0, float x1, float z1)
{
    float dx = x1 - x0, dz = z1 - z0, d = sqrtf(dx * dx + dz * dz);
    int n = (int)(d / 0.7f) + 1;
    float nx = d > 0.01f ? -dz / d : 0.0f, nz = d > 0.01f ? dx / d : 0.0f;
    for (int i = 1; i <= n; i++) {
        float t = (float)i / n;
        for (int k = -1; k <= 1; k++) {                       // tres carriles: el cuerpo es ancho
            int cx = (int)((x0 + dx * t + nx * 0.45f * k) / CS), cz = (int)((z0 + dz * t + nz * 0.45f * k) / CS);
            if (cx < 0 || cz < 0 || cx >= MW || cz >= MH || AI_SOLID(layer, cz, cx)) return 0;
        }
    }
    return 1;
}
#define FRENZY_WARN  10.0f      // segundos que tienes para buscar un casillero antes de que enloquezca
#define FRENZY_T     20.0f      // segundos que dura enloquecido
#define FRENZY_MUL   10.0f      // su velocidad se multiplica por 10
static float frenzy_w;          // >0: cuenta atras del aviso "viene por ti"
static int   frenzy_go;         // aviso de que acaba de enloquecer (para el rugido)
static float frenzy_t;          // >0: el monstruo esta enloquecido y te busca por todo el mapa
static int   frenzy_msg;        // cuadros que se muestra el mensaje
static int need_flow = 1, last_layer = -1, last_foot = 0;
static void frenzy_start(void) { frenzy_w = FRENZY_WARN; frenzy_t = 0.0f; frenzy_msg = 240; }   // estado de la IA (se reinicia en reset_game: online necesita partir igual)
// Luz UV contra el monstruo: si le apuntas con la linterna UV durante 3 segundos se queda ciego 10 segundos
// (se tapa los ojos, se detiene y no puede atraparte). Pasa lo mismo para los dos jugadores en pantalla dividida / online.
static void mon_uv_update(float dt)
{
    int aim = 0;
    if (mon_blind_t <= 0.0f)
        for (int i = 0; i < num_players && !aim; i++) {
            const Player *Q = &P[i];
            if (!Q->flash_on || !Q->uv_on || Q->climbing || Q->cur_layer != mlayer) continue;
            float dx = sx_ - Q->px, dz = sz_ - Q->pz, dy = (mon_y + 1.3f) - Q->cam_y;
            float d = sqrtf(dx * dx + dy * dy + dz * dz);
            if (d < 0.5f || d > 16.0f) continue;                                     // alcance de la luz UV
            float pe = clampf(Q->pitch, -1.2f, 1.3f) - 0.04f;
            float ax = sinf(Q->yaw) * cosf(pe), ay = sinf(pe), az = cosf(Q->yaw) * cosf(pe);
            if ((dx * ax + dy * ay + dz * az) / d < 0.96f) continue;                // dentro del haz (unos 16 grados)
            if (!mon_clear(mlayer, Q->px, Q->pz, sx_, sz_)) continue;               // sin paredes en medio
            aim = 1;
            mon_blind_yaw = atan2f(Q->px - sx_, Q->pz - sz_);                       // se queda mirando hacia quien lo cego
        }
    uvc_aim = aim;
    if (mon_blind_t > 0.0f) mon_uv_t = 0.0f;
    else if (aim) {
        mon_uv_t += dt;
        if (mon_uv_t >= 3.0f) { mon_uv_t = 0.0f; mon_blind_t = 10.0f; }
    } else mon_uv_t = fmaxf(0.0f, mon_uv_t - dt * 1.5f);                             // si dejas de apuntar, se recupera rapido
}

// A que jugador ve el monstruo ahora (el mas cercano dentro de su cono de 75 grados y a menos de 30 m, sin paredes en medio), o -1
static int mon_vision(void)
{
    if (mon_blind_t > 0.0f) return -1;                        // ciego
    float hx = sinf(mon_face), hz = cosf(mon_face);
    int best = -1;
    float bd = 1e9f;
    for (int i = 0; i < num_players; i++) {
        const Player *Q = &P[i];
        if (pl_dn[i] || Q->cur_layer != mlayer || Q->climbing || Q->hide_id >= 0) continue;     // escondido en un casillero: no te ve (y a un caido tampoco lo busca)
        float dx = Q->px - sx_, dz = Q->pz - sz_, d2 = dx * dx + dz * dz;
        if (d2 > MON_SIGHT * MON_SIGHT || d2 >= bd) continue;
        float d = sqrtf(d2);
        if (d > 1.0f && (dx * hx + dz * hz) / d < MON_FOV_COS) continue;      // fuera del cono: no te ve
        if (!mon_clear(mlayer, sx_, sz_, Q->px, Q->pz)) continue;
        bd = d2; best = i;
    }
    return best;
}

static float wrap_pi(float a) { while (a > PI_F) a -= 2.0f * PI_F; while (a < -PI_F) a += 2.0f * PI_F; return a; }

#define PL_WALK_SPD 2.8f      // velocidad maxima de caminata del jugador (m/s)
#define PL_RUN_SPD  5.2f      // velocidad de carrera del jugador
#define MON_WALK_K  2.0f      // el monstruo camina (patrulla / va a donde oyo) 2 veces tu caminata
#define MON_RUN_K   2.0f      // el monstruo corre (te ve) 2 veces tu carrera
static void update_monster(float dt, int notes)
{
    if (frenzy_w > 0.0f) {                                    // aviso: tienes unos segundos para esconderte
        frenzy_w -= dt;
        if (frenzy_w <= 0.0f) { frenzy_w = 0.0f; frenzy_t = FRENZY_T; frenzy_go = 1; need_flow = 1; }
    } else if (frenzy_t > 0.0f) { frenzy_t -= dt; if (frenzy_t < 0.0f) frenzy_t = 0.0f; }
    mon_cover += ((mon_blind_t > 0.0f ? 1.0f : 0.0f) - mon_cover) * clampf(dt * (mon_blind_t > 0.0f ? 7.0f : 3.0f), 0.0f, 1.0f);
    if (mon_blind_t > 0.0f) {                                 // ciego: se queda quieto tapandose los ojos
        mon_blind_t -= dt;
        mon_spd  += (0.0f - mon_spd)  * clampf(dt * 8.0f, 0.0f, 1.0f);
        mon_runf += (0.0f - mon_runf) * clampf(dt * 8.0f, 0.0f, 1.0f);
        mon_face = mon_blind_yaw;
        if (mon_blind_t < 0.0f) mon_blind_t = 0.0f;
        return;
    }
    int pl = cur_layer;
    int fr = frenzy_t > 0.0f;

    // ---- que sabe el monstruo: 2 = te ve, 1 = te oye / va a donde te vio, 0 = patrulla ----
    int chase = 0;
    if (mon_seen) { mon_lx = px; mon_lz = pz; mon_ll = pl; mon_has = 1; mon_look_t = 0.0f; chase = 2; }
    else if (fr && hide_id < 0) { mon_lx = px; mon_lz = pz; mon_ll = pl; mon_has = 1; mon_look_t = 0.0f; chase = 1; }   // enloquecido: sabe donde estas (en cualquier parte, hasta en la alcantarilla)
    else if (mlayer == pl && !climbing && hide_id < 0) {      // oido: agachado casi no se te oye, corriendo se te oye lejos
        float hdx = px - sx_, hdz = pz - sz_, hd = sqrtf(hdx * hdx + hdz * hdz);
        float sp = sqrtf(vel_x * vel_x + vel_z * vel_z);
        float hr = crouched ? 3.0f : (sp > 4.0f ? 16.0f : (sp > 1.0f ? 9.0f : 4.0f));
        if (hd < hr) { mon_lx = px; mon_lz = pz; mon_ll = pl; mon_has = 1; mon_look_t = 0.0f; chase = 1; }
    }
    if (noise_on && !chase && !fr && mlayer == noise_layer) {   // oyo un ruido: va a donde sono
        float ndx = noise_x - sx_, ndz = noise_z - sz_;
        if (ndx * ndx + ndz * ndz < noise_r * noise_r) { mon_lx = noise_x; mon_lz = noise_z; mon_ll = noise_layer; mon_has = 1; mon_look_t = 0.0f; }
    }
    float tx, tz;
    if (chase) { tx = px; tz = pz; }
    else if (mon_has) { tx = mon_lx; tz = mon_lz; chase = 1; }       // va al ultimo sitio donde te vio
    else {                                                            // patrulla
        if (!mon_wp_ok) {
            for (int k = 0; k < 40 && !mon_wp_ok; k++) {
                unsigned int h = hash2((int)game_seed + mon_wp_n * 31 + k, 777 + mon_wp_n);
                int wx = (int)(h % MW), wz = (int)((h >> 8) % MH);
                float cx = (wx + 0.5f) * CS, cz = (wz + 0.5f) * CS;
                if (AI_SOLID(mlayer, wz, wx)) continue;
                if ((cx - sx_) * (cx - sx_) + (cz - sz_) * (cz - sz_) < 14.0f * 14.0f) continue;
                mon_wpx = cx; mon_wpz = cz; mon_wp_ok = 1; need_flow = 1;
            }
            mon_wp_n++;
        }
        tx = mon_wpx; tz = mon_wpz;
    }
    if (chase != mon_last_chase) { need_flow = 1; mon_last_chase = chase; }

    int mcx = (int)(sx_ / CS), mcz = (int)(sz_ / CS);
    if (mcx < 0 || mcz < 0 || mcx >= MW || mcz >= MH) return;

    // si te perdio de vista y llega al ultimo sitio, se queda mirando alrededor y luego patrulla
    float ldx = tx - sx_, ldz = tz - sz_;
    if (!mon_seen && !(fr && hide_id < 0) && mon_has && mlayer == mon_ll && ldx * ldx + ldz * ldz < 2.2f * 2.2f && chase == 1) {
        int near_ladder = 0;
        for (int i = 0; i < NMH; i++) {
            float hx = (manholes[i][0] + 0.5f) * CS - sx_, hz = (manholes[i][1] + 0.5f) * CS - sz_;
            if (hx * hx + hz * hz < 3.5f * 3.5f) near_ladder = 1;
        }
        if (!(near_ladder && mlayer != pl)) { mon_has = 0; mon_look_t = 4.0f; mon_wp_ok = 0; chase = 0; }
    }

    if (mon_has && mlayer != pl) {            // te vio bajar/subir: va a la escalera
        tx = (manholes[last_ladder][0] + 0.5f) * CS;
        tz = (manholes[last_ladder][1] + 0.5f) * CS;
        float ex = tx - sx_, ez = tz - sz_;
        if (ex * ex + ez * ez < 1.8f * 1.8f) {
            mon_wait += dt;
            if (mon_wait > (fr ? 0.8f : 4.0f)) {            // sube o baja por la escalera
                mlayer = pl; mon_y = pl ? SEWER_Y : 0.0f;
                sx_ = tx; sz_ = tz - 1.4f; mon_wait = 0.0f; need_flow = 1; mon_has = 0; mon_wp_ok = 0; mon_look_t = 3.0f;
            }
        }
        chase = 1;
    } else mon_wait = 0.0f;

    if (frame_no % 15 == 0 || need_flow || last_layer != mlayer) {
        compute_flow(mlayer, (int)(tx / CS), (int)(tz / CS));
        need_flow = 0; last_layer = mlayer;
        if (!chase && dist_map[mcz][mcx] == 9999) mon_wp_ok = 0;      // punto de patrulla inalcanzable: elige otro
    }
    float gx = tx, gz = tz;
    int direct = 0;                                           // 1 = camino recto libre hasta el objetivo
    if (mlayer == pl || !mon_has) {
        float pdx0 = tx - sx_, pdz0 = tz - sz_, pd0 = sqrtf(pdx0 * pdx0 + pdz0 * pdz0);
        if (pd0 < 30.0f && mon_clear(mlayer, sx_, sz_, tx, tz)) {
            direct = 1;
            if (chase == 2) {
                float lead = clampf(pd0 / 6.0f, 0.0f, 0.9f);      // se adelanta a tu carrera: apunta a donde vas a estar
                float ix = px + vel_x * lead, iz = pz + vel_z * lead;
                if (mon_clear(mlayer, sx_, sz_, ix, iz)) { gx = ix; gz = iz; }
            }
        }
    }
    if (!direct && (mcx != (int)(tx / CS) || mcz != (int)(tz / CS))) {
        static const int dx[4] = {1, -1, 0, 0}, dz[4] = {0, 0, 1, -1};
        int best = dist_map[mcz][mcx], bx = mcx, bz = mcz;
        for (int k = 0; k < 4; k++) {
            int nx = mcx + dx[k], nz = mcz + dz[k];
            if (nx < 0 || nz < 0 || nx >= MW || nz >= MH) continue;
            if (dist_map[nz][nx] < best) { best = dist_map[nz][nx]; bx = nx; bz = nz; }
        }
        gx = (bx + 0.5f) * CS; gz = (bz + 0.5f) * CS;
        // atajo: si ya ve libre el centro de la celda siguiente-siguiente, no hace zigzag en las esquinas
        int cx2 = bx + (bx - mcx), cz2 = bz + (bz - mcz);
        if (cx2 >= 0 && cz2 >= 0 && cx2 < MW && cz2 < MH && dist_map[cz2][cx2] < dist_map[bz][bx]) {
            float ax = (cx2 + 0.5f) * CS, az = (cz2 + 0.5f) * CS;
            if (mon_clear(mlayer, sx_, sz_, ax, az)) { gx = ax; gz = az; }
        }
    }
    float ex = gx - sx_, ez = gz - sz_;
    float len = sqrtf(ex * ex + ez * ez);
    float spd_now = 0.0f;
    float want_face = mon_face, turn_rate = 3.5f;
    if (mon_look_t > 0.0f && !chase) {                        // te perdio: se queda quieto mirando a los lados
        mon_look_t -= dt;
        want_face = mon_face + 0.0f;
        mon_face += sinf(mon_look_t * 2.2f) * 1.6f * dt;      // barre la vista de lado a lado
    } else if (len > 0.01f) {
        float speed = 1.8f + 0.5f * notes;                                    // (formula vieja: solo para el modo enloquecido)
        if (chase == 2) speed *= 1.7f;
        else if (chase == 1) speed *= 1.3f;
        else speed = 1.2f + 0.3f * notes;
        if (speed > 4.6f) speed = 4.6f;
        if (diff_mul != 1.0f) { speed *= diff_mul; if (speed > 5.0f) speed = 5.0f; }
        if (!fr) {                                                            // normal: el DOBLE que tu. Camina = 2 x tu caminata, te ve = 2 x tu carrera
            speed = (chase == 2 ? MON_RUN_K * PL_RUN_SPD : MON_WALK_K * PL_WALK_SPD) * diff_mul;   // dificultad: facil x0.8, media x1.0, dificil x1.2
        }
        if (fr) speed *= FRENZY_MUL;                                          // enloquecido: velocidad x10
        sx_ += ex / len * speed * dt;
        sz_ += ez / len * speed * dt;
        spd_now = speed;
        want_face = atan2f(ex, ez);
        turn_rate = chase == 2 ? 6.0f : 3.5f;
        float df = wrap_pi(want_face - mon_face), mx = turn_rate * dt;       // gira hacia donde camina (no de golpe)
        mon_face += df > mx ? mx : (df < -mx ? -mx : df);
    }
    mon_spd  += (spd_now - mon_spd) * clampf(dt * 6.0f, 0.0f, 1.0f);
    mon_runf += (((mon_spd > 2.6f) ? 1.0f : 0.0f) - mon_runf) * clampf(dt * 5.0f, 0.0f, 1.0f);
    mon_phase += fminf(mon_spd, 7.0f) * dt * (3.0f - 1.2f * mon_runf);     // cadencia ligada a la velocidad: los pies no patinan
    {   // pisadas pesadas: cada apoyo sacude la camara si el monstruo esta cerca
        int fs = (int)floorf(mon_phase / PI_F);
        if (fs != last_foot) {
            last_foot = fs;
            mon_foot_event = 1;                   // cada jugador lo recibe despues, segun su distancia
        }
    }
}

// ---------------- Reinicio ----------------
// Coloca un botiquin COLGADO EN LA PARED dentro de cada estructura con puerta: la pared interior mas cercana al lugar de su llave,
// a ~1.2 m de altura, con el frente hacia el cuarto, lejos de las puertas y sin chocar con muebles.
static void place_medkits(void)
{
    static const unsigned char slot_of_door[NMK] = { 1, 3, 2, 4, 5, 7, 6, 8 };     // puerta i -> lugar (adentro) de esa estructura
    static const float DX[4] = { 1.0f, -1.0f, 0.0f, 0.0f }, DZ[4] = { 0.0f, 0.0f, 1.0f, -1.0f };
    const float BACK = 0.151f;                                                    // distancia del centro del modelo a la pared (0.136 de fondo + holgura)
    int sv_l = cur_layer, sv_c = climbing;
    cur_layer = 0; climbing = 0;                                                  // la superficie (aunque la partida anterior terminara en la alcantarilla)
    for (int i = 0; i < NMK; i++) {
        float cx = slot_xz[slot_of_door[i]][0], cz = slot_xz[slot_of_door[i]][1];
        float best = 1e9f, bx = cx, bz = cz, ba = atan2f(doors[i].x - cx, doors[i].z - cz), by = 0.0f;
        for (int ring = 0; ring < 9; ring++) {
            float r = 0.5f * (float)ring;
            int na = ring ? 16 : 1;
            for (int k = 0; k < na; k++) {
                float ang = (float)k * (2.0f * PI_F / 16.0f);
                float x = cx + sinf(ang) * r, z = cz + cosf(ang) * r;
                if (blocked(x, z, 0.3f)) continue;
                int ok = 1;                                                       // se llega caminando desde el centro (no al otro lado de una pared)
                for (int st = 1; st <= 8 && ok; st++) { float u = (float)st / 8.0f; if (blocked(cx + (x - cx) * u, cz + (z - cz) * u, 0.25f)) ok = 0; }
                if (!ok) continue;
                for (int d4 = 0; d4 < 4; d4++) {
                    float d = -1.0f;
                    for (float dd = 0.10f; dd <= 1.30f; dd += 0.05f) if (solid(x + DX[d4] * dd, z + DZ[d4] * dd)) { d = dd; break; }
                    if (d < 0.0f) continue;
                    float mx = x + DX[d4] * (d - BACK), mz = z + DZ[d4] * (d - BACK);
                    if (blocked(mx, mz, 0.08f) || blocked(mx - DX[d4] * 0.9f, mz - DZ[d4] * 0.9f, 0.3f)) continue;     // espacio libre delante para agarrar
                    int near_door = 0;
                    for (int j = 0; j < ND; j++) { float ddx = mx - doors[j].x, ddz = mz - doors[j].z, rr = doors[j].hw + 1.2f; if (ddx * ddx + ddz * ddz < rr * rr) near_door = 1; }
                    if (near_door) continue;
                    float score = r + 2.0f * d;                                   // cerca del centro de la estructura y de la pared
                    if (score < best) { best = score; bx = mx; bz = mz; ba = atan2f(-DX[d4], -DZ[d4]); by = 1.20f; }
                }
            }
        }
        if (i == 3) { bx = 67.299f; bz = 64.0f; ba = atan2f(-1.0f, 0.0f); by = 1.20f; }   // iglesia: botiquin en la pared izquierda segun se entra (en el juego el este queda a la izquierda al mirar al norte)
        if (i == 2) { bx = 331.649f; bz = 312.0f; ba = atan2f(-1.0f, 0.0f); by = 1.20f; }   // granero: en la pared este
        if (i == 0) { bx = 228.351f; bz = 284.5f; ba = atan2f(1.0f, 0.0f); by = 1.20f; }   // supermercado: botiquin en la pared oeste, entre los dos estantes
        if (i == 7) { bx = 183.449f; bz = 170.0f; ba = atan2f(-1.0f, 0.0f); by = 1.20f; }   // caseta de la antena: botiquin en la pared este
        if (i == 4) { bx = 304.351f; bz = 170.0f; ba = atan2f(1.0f, 0.0f); by = 1.20f; }   // refugio: botiquin en la pared derecha segun se entra (oeste)
        mk_x[i] = bx; mk_z[i] = bz; mk_a[i] = ba; mk_y[i] = by;
        mk_open[i] = 0; mk_t[i] = 0.0f; mk_bd[i] = 2;
    }
    pl_bnd[0] = pl_bnd[1] = 0;
    for (int k = 0; k < NBF; k++) bf_on[k] = 0;
    lt_on = 1; lt_l = 0; lt_x = 197.0f; lt_z = 359.0f;                  // encendedor: en el camino, cerca del inicio
    for (int q_ = 0; q_ < MAXP; q_++) { pl_lt[q_] = 0; pl_lt_on[q_] = 0; }
    cur_layer = sv_l; climbing = sv_c;
}

static void reset_game(void)
{
    spec_mode = 0; spec_day = 0;
    if (net_online) game_seed = game_seed * 1664525u + 1013904223u;   // online: los dos juegos avanzan igual
    else game_seed = (unsigned int)frame_no;
    need_flow = 1; last_layer = -1; last_foot = 0;
    sx_ = MON_X; sz_ = MON_Z; mlayer = 0; mon_y = 0.0f; mon_wait = 0.0f;
    for (int i = 0; i < 3; i++) { notes_got[i] = 0; notes_off[i] = 0; notes_used[i] = 0; notes_frz[i] = 0; }
    for (int i = 0; i < ND; i++) { door_open[i] = 0; door_ang[i] = 0.0f; }          // puertas cerradas, items en su sitio
    for (int i = 0; i < NIT; i++) item_got[i] = 0;
    for (int i = 0; i < 4; i++) have_key[i] = 0;
    for (int i = 0; i < 2; i++) { have_code[i] = 0; code_num[i] = 1000 + (int)(hash2(game_seed + 17 * i, 91 + 37 * i) % 9000u); }   // codigos distintos cada partida
    key_set = (int)(hash2((int)game_seed, 4242) % NKSET);                       // set de llaves al azar (no repite el de la partida anterior)
    if (key_set == last_key_set) key_set = (key_set + 1 + (int)(hash2((int)game_seed, 99) % (NKSET - 1))) % NKSET;
    last_key_set = key_set;
    place_keys(key_set);
    place_medkits();
    state = 0; state_timer = 0;
    mon_phase = 0.0f; mon_spd = 0.0f; mon_runf = 0.0f; mon_uv_t = 0.0f; uvc_aim = 0; mon_blind_t = 0.0f; mon_cover = 0.0f;
    mon_foot_event = 0; js_victim = 0; mon_target = 0; noise_on = 0; for (int q_ = 0; q_ < MAXP; q_++) { pl_dn[q_] = 0; pl_rv[q_] = 0.0f; pl_spw[q_] = 0; pl_bnd[q_] = 0; rv_on[q_] = 0; rv_tgt[q_] = -1; }
    mon_face = atan2f(SPAWN_X - MON_X, SPAWN_Z - MON_Z); mon_seen = 0; mon_has = 0; mon_wp_ok = 0; mon_wp_n = 0; mon_look_t = 0.0f; mon_last_chase = 0; frenzy_t = 0.0f; frenzy_w = 0.0f; frenzy_go = 0; frenzy_msg = 0;
    for (int i = 0; i < MAXP; i++) {
        carry = 0;
        px = SPAWN_X + (i == 0 ? 0.0f : (i == 1 ? 1.8f : (i == 2 ? -1.8f : 3.6f))); pz = SPAWN_Z; yaw = PI_F;      // los demas jugadores aparecen al lado
        foot_y = 0.0f; cur_layer = 0; climbing = 0; climb_dir = 0; last_ladder = 0; flash_on = 1;
        pitch = 0.0f; cpitch = 1.0f; spitch = 0.0f;
        stamina = 1.0f; stam_delay = 0.0f; exhausted = 0; jump_h = 0.0f; jump_vy = 0.0f;
        crouched = 0; crouch_f = 0.0f;
        walk_ph = 0.0f; walk_amp = 0.0f; step_imp = 0.0f; walk_step = 0; mon_thud = 0.0f;
        cam_rc = 1.0f; cam_rs = 0.0f; p_moving = 0; p_near = -1;
        vel_x = 0.0f; vel_z = 0.0f; step_kick = 0.0f; walk_spd = 0.0f; det_t = 0.0f; det_up = 0.0f; emoji_open = 0; emoji_sel = 0; emoji_id = -1; emoji_t = 0.0f; dance_open = 0; dance_sel = 0; dance_id = -1; dance_t = 0.0f; hide_id = -1; hide_exp = 0; hide_hold = 0.0f;
        fx = sinf(yaw); fz = cosf(yaw); rx = cosf(yaw); rz = -sinf(yaw);
        cam_y = EYE; amb_r = 22.0f; light_flick = 1.0f;
        has_map = 0; map_open = 0; map_msg = 0; uv_on = 0; uv_hold = 0.0f;
        door_msg = 0; door_msg_id = 0; code_door = -1; code_val = 0; code_pos = 0; inv_open = 0;
        player_save(i);
    }
    player_load(0);
}

