static void key_rgb_of(int code, float *o)       // color de la llave: 1..4 = llaves de color, 5..7 = llaves finales (plata azulada)
{
    if (code >= 5) { o[0] = 170.f; o[1] = 226.f; o[2] = 245.f; }
    else { o[0] = key_rgb[code - 1][0]; o[1] = key_rgb[code - 1][1]; o[2] = key_rgb[code - 1][2]; }
}

// Llave tirada en el suelo (sin brillo)
static void draw_key_floor(float x, float z, float a, int code)
{
    float col[3], ca = cosf(a), sa = sinf(a);
    const float s = 0.42f / 13100.0f;   // 0.42 m de largo
    key_rgb_of(code, col);
    for (int f = 0; f < 108; f++) {
        float p[4][3], fc[3];
        for (int j = 0; j < 4; j++) {
            const short *m = kmv[kmf[f][j]];
            float lx = (float)m[1] * s, lz = (float)m[2] * s, hy = ((float)m[0] + 1004.0f) * s;
            p[j][0] = x + lx * ca + lz * sa; p[j][1] = tab_h(x, z) + hy + 0.004f; p[j][2] = z - lx * sa + lz * ca;
        }
        float k = (float)kms[f] / 255.0f;
        fc[0] = col[0] * k; fc[1] = col[1] * k; fc[2] = col[2] * k;
        quad_sub(p, fc, 1, 0.05f);
    }
}

// Llave en la mano (vista en primera persona, como en Granny): sube desde abajo cuando la agarras
static void draw_key_hand(float t)
{
    static float up[MAXP];
    int sl = pl_cur, tgt = carry > 0;
    up[sl] += ((float)tgt - up[sl]) * 0.16f;
    if (up[sl] < 0.02f) return;
    float e = up[sl] * up[sl] * (3.0f - 2.0f * up[sl]), col[3];
    key_rgb_of(carry > 0 ? carry : 1, col);
    rd_th = 0.55f + 0.55f * (1.0f - e); rd_ya = -0.30f - 0.3f * (1.0f - e);
    rd_ox = -0.17f + 0.010f * walk_amp * sinf(walk_ph + 0.5f);
    rd_oy = -0.20f - 0.45f * (1.0f - e) + 0.008f * walk_amp * sinf(2.0f * walk_ph + 0.4f) - 0.015f * step_imp + sinf(t * 1.4f) * 0.002f;
    rd_oz = 0.42f;
    const float s = 0.34f / 13100.0f;
    float pt[4][3];
    vm_mode = 1;
    {   // mano (bloque de piel) agarrando la argolla
        float sk[3] = { hand_col[4][0], hand_col[4][1], hand_col[4][2] }, sk2[3] = { hand_col[2][0], hand_col[2][1], hand_col[2][2] };
        rd_box(0.0f, -0.050f, 0.030f, 0.036f, 0.034f, 0.030f, sk, sk2);
        rd_box(0.040f, -0.045f, 0.000f, 0.010f, 0.026f, 0.018f, sk, sk2);
        rd_box(-0.040f, -0.045f, 0.000f, 0.010f, 0.026f, 0.018f, sk, sk2);
    }
    for (int f = 0; f < 108; f++) {
        float fc[3], k = (float)kms[f] / 255.0f;
        fc[0] = col[0] * k; fc[1] = col[1] * k; fc[2] = col[2] * k;
        for (int j = 0; j < 4; j++) {
            const short *m = kmv[kmf[f][j]];
            rd_pt((float)m[2] * s, -(float)m[1] * s + 0.03f, (float)m[0] * s, pt[j]);
        }
        V v[4];
        for (int j = 0; j < 4; j++) { v[j].x = pt[j][0]; v[j].y = pt[j][1]; v[j].z = pt[j][2]; v[j].r = fc[0]; v[j].g = fc[1]; v[j].b = fc[2]; }
        tri_cam(v[0], v[1], v[2]); tri_cam(v[0], v[2], v[3]);
    }
    vm_mode = 0;
}

// Venda en la mano izquierda (como la llave): sube desde abajo al agarrarla. Si ya llevas una llave, se pone un poco mas a la izquierda.
// Se ven hasta 2 rollos (uno atras del otro); el numero exacto esta en "VENDAS: n".
static void draw_bandage_hand(float t)
{
    static float up[MAXP];
    int sl = pl_cur, nb = pl_bnd[pl_cur], tgt = nb > 0;
    up[sl] += ((float)tgt - up[sl]) * 0.16f;
    if (up[sl] < 0.02f) return;
    float e = up[sl] * up[sl] * (3.0f - 2.0f * up[sl]);
    rd_th = 0.50f + 0.50f * (1.0f - e); rd_ya = -0.20f - 0.30f * (1.0f - e);
    rd_ox = (carry > 0 ? -0.35f : -0.18f) + 0.010f * walk_amp * sinf(walk_ph + 0.5f);
    rd_oy = -0.21f - 0.45f * (1.0f - e) + 0.008f * walk_amp * sinf(2.0f * walk_ph + 0.4f) - 0.015f * step_imp + sinf(t * 1.3f) * 0.002f;
    rd_oz = 0.40f;
    vm_mode = 1;
    {   // mano (bloques de piel) sosteniendo el rollo
        float sk[3] = { hand_col[4][0], hand_col[4][1], hand_col[4][2] }, sk2[3] = { hand_col[2][0], hand_col[2][1], hand_col[2][2] };
        rd_box(0.0f, -0.046f, 0.010f, 0.036f, 0.016f, 0.036f, sk, sk2);
        rd_box(0.058f, -0.020f, 0.004f, 0.012f, 0.030f, 0.020f, sk, sk2);
        rd_box(-0.058f, -0.020f, 0.004f, 0.012f, 0.030f, 0.020f, sk, sk2);
    }
    const float R = 0.036f, HL = 0.046f;
    int nr = nb > 2 ? 2 : nb;
    for (int r = 0; r < nr; r++) {
        float cx = 0.0f, cy = 0.0f + 0.004f * r, cz = 0.0f + 0.080f * r;
        float ring[2][12][3];
        for (int en = 0; en < 2; en++)
            for (int k = 0; k < 12; k++) {
                float ph = (float)k * (2.0f * PI_F / 12.0f);
                rd_pt(cx + (en ? HL : -HL), cy + R * cosf(ph), cz + R * sinf(ph), ring[en][k]);
            }
        for (int k = 0; k < 12; k++) {                               // lados
            int k2 = (k + 1) % 12;
            float sh = 0.74f + 0.26f * (0.5f + 0.5f * cosf((float)k * (2.0f * PI_F / 12.0f) - 0.9f));
            V v[4];
            const float *a = ring[0][k], *b = ring[0][k2], *c = ring[1][k2], *d = ring[1][k];
            const float *pp[4] = { a, b, c, d };
            for (int j = 0; j < 4; j++) { v[j].x = pp[j][0]; v[j].y = pp[j][1]; v[j].z = pp[j][2]; v[j].r = 238.f * sh; v[j].g = 232.f * sh; v[j].b = 212.f * sh; }
            tri_cam(v[0], v[1], v[2]); tri_cam(v[0], v[2], v[3]);
        }
        for (int en = 0; en < 2; en++) {                              // tapas
            float cc[3]; rd_pt(cx + (en ? HL : -HL), cy, cz, cc);
            for (int k = 0; k < 12; k += 2) {
                const float *pp[4] = { cc, ring[en][k], ring[en][(k + 1) % 12], ring[en][(k + 2) % 12] };
                V v[4];
                for (int j = 0; j < 4; j++) { v[j].x = pp[j][0]; v[j].y = pp[j][1]; v[j].z = pp[j][2]; v[j].r = 250.f; v[j].g = 246.f; v[j].b = 232.f; }
                tri_cam(v[0], v[1], v[2]); tri_cam(v[0], v[2], v[3]);
            }
        }
    }
    vm_mode = 0;
}

// Cilindro con eje en X (camara) para la animacion de vendar
static void rd_cyl_x(float cx, float cy, float cz, float hl, float R, const float *c0, float spin, int light)
{
    float ring[2][10][3];
    for (int en = 0; en < 2; en++)
        for (int k = 0; k < 10; k++) {
            float ph = spin + (float)k * (2.0f * PI_F / 10.0f);
            rd_pt(cx + (en ? hl : -hl), cy + R * cosf(ph), cz + R * sinf(ph), ring[en][k]);
        }
    for (int k = 0; k < 10; k++) {
        int k2 = (k + 1) % 10;
        float sh = light ? 0.78f + 0.22f * (0.5f + 0.5f * cosf((float)k * (2.0f * PI_F / 10.0f) - 1.2f)) : 1.0f;
        const float *pp[4] = { ring[0][k], ring[0][k2], ring[1][k2], ring[1][k] };
        V v[4];
        for (int j = 0; j < 4; j++) { v[j].x = pp[j][0]; v[j].y = pp[j][1]; v[j].z = pp[j][2]; v[j].r = c0[0] * sh; v[j].g = c0[1] * sh; v[j].b = c0[2] * sh; }
        tri_cam(v[0], v[1], v[2]); tri_cam(v[0], v[2], v[3]);
    }
}

// Brazo de bloque (como Minecraft): prisma cuadrado de p0 (hombro, hacia la camara) a p1 (punto), manga en el primer tramo y piel en el resto con
// puño cuadrado al final. Solo se dibujan las caras que miran a la camara.
static void rd_limb(const float p0[3], const float p1[3], float hf, const float *skin, const float *sleeve, float sleeve_frac)
{
    float a[3] = { p1[0] - p0[0], p1[1] - p0[1], p1[2] - p0[2] };
    float al = sqrtf(a[0] * a[0] + a[1] * a[1] + a[2] * a[2]);
    if (al < 1e-4f) return;
    for (int i = 0; i < 3; i++) a[i] /= al;
    float ref[3] = { 0.0f, 1.0f, 0.0f };
    if (fabsf(a[1]) > 0.95f) { ref[1] = 0.0f; ref[2] = 1.0f; }
    float u[3] = { ref[1] * a[2] - ref[2] * a[1], ref[2] * a[0] - ref[0] * a[2], ref[0] * a[1] - ref[1] * a[0] };
    float ul = sqrtf(u[0] * u[0] + u[1] * u[1] + u[2] * u[2]);
    for (int i = 0; i < 3; i++) u[i] /= ul;
    float v[3] = { a[1] * u[2] - a[2] * u[1], a[2] * u[0] - a[0] * u[2], a[0] * u[1] - a[1] * u[0] };
    static const float sx[4] = { -1.0f, 1.0f, 1.0f, -1.0f }, sy[4] = { -1.0f, -1.0f, 1.0f, 1.0f };
    for (int seg = 0; seg < 2; seg++) {
        float t0 = seg ? sleeve_frac : 0.0f, t1 = seg ? 1.0f : sleeve_frac;
        const float *col = seg ? skin : sleeve;
        float c[2][4][3];                                            // anillos de esquinas en el espacio de camara
        for (int e = 0; e < 2; e++) {
            float tt = e ? t1 : t0;
            for (int k = 0; k < 4; k++) {
                float lp[3];
                for (int i = 0; i < 3; i++) lp[i] = p0[i] + (p1[i] - p0[i]) * tt + u[i] * hf * sx[k] + v[i] * hf * sy[k];
                rd_pt(lp[0], lp[1], lp[2], c[e][k]);
            }
        }
        float cen[3], ce[3];
        for (int i = 0; i < 3; i++) { cen[i] = 0.0f; for (int e = 0; e < 2; e++) for (int k = 0; k < 4; k++) cen[i] += c[e][k][i] * 0.125f; }
        for (int k = 0; k < 4; k++) {                                // 4 lados
            int k2 = (k + 1) & 3;
            const float *q[4] = { c[0][k], c[0][k2], c[1][k2], c[1][k] };
            for (int i = 0; i < 3; i++) ce[i] = (q[0][i] + q[1][i] + q[2][i] + q[3][i]) * 0.25f;
            float vis = (ce[0] - cen[0]) * (-ce[0]) + (ce[1] - cen[1]) * (-ce[1]) + (ce[2] - cen[2]) * (-ce[2]);
            if (vis <= 0.0f) continue;
            float sh = 0.62f + 0.38f * clampf(0.5f + 0.9f * (ce[1] - cen[1]) / hf * 0.5f - 0.35f * (ce[0] - cen[0]) / hf * 0.5f, 0.0f, 1.0f);
            V w[4];
            for (int j = 0; j < 4; j++) { w[j].x = q[j][0]; w[j].y = q[j][1]; w[j].z = q[j][2]; w[j].r = col[0] * sh; w[j].g = col[1] * sh; w[j].b = col[2] * sh; }
            tri_cam(w[0], w[1], w[2]); tri_cam(w[0], w[2], w[3]);
        }
        if (seg) {                                                   // puno: tapa del extremo p1
            const float *q[4] = { c[1][0], c[1][1], c[1][2], c[1][3] };
            for (int i = 0; i < 3; i++) ce[i] = (q[0][i] + q[1][i] + q[2][i] + q[3][i]) * 0.25f;
            if ((ce[0] - cen[0]) * (-ce[0]) + (ce[1] - cen[1]) * (-ce[1]) + (ce[2] - cen[2]) * (-ce[2]) > 0.0f) {
                V w[4];
                for (int j = 0; j < 4; j++) { w[j].x = q[j][0]; w[j].y = q[j][1]; w[j].z = q[j][2]; w[j].r = col[0] * 0.85f; w[j].g = col[1] * 0.85f; w[j].b = col[2] * 0.85f; }
                tri_cam(w[0], w[1], w[2]); tri_cam(w[0], w[2], w[3]);
            }
        }
    }
}

// Animacion de poner la venda al companero caido: dos manos. La izquierda sujeta el brazo, la derecha rodea el brazo con el rollo
// y la venda va cubriendolo poco a poco segun avanza la carga de revivir.
static void draw_revive_anim(float t)
{
    static float up[MAXP];
    int sl = pl_cur;
    float p = clampf((rv_tgt[pl_cur] >= 0 ? pl_rv[rv_tgt[pl_cur]] : 0.0f) / REVIVE_T, 0.0f, 1.0f);
    up[sl] += ((float)rv_on[pl_cur] - up[sl]) * 0.14f;
    if (up[sl] < 0.02f) return;
    float e = up[sl] * up[sl] * (3.0f - 2.0f * up[sl]);
    float sk[3] = { hand_col[4][0], hand_col[4][1], hand_col[4][2] }, sk2[3] = { hand_col[2][0], hand_col[2][1], hand_col[2][2] };
    static const float wh[3] = { 238.f, 232.f, 212.f }, wh2[3] = { 214.f, 208.f, 190.f };
    // el vendaje se pone sobre el cuerpo REAL del companero caido: se busca donde esta en la vista (espacio de camara)
    float tcx = 0.0f, tcy = -0.20f, tcz = 0.70f;
    if (rv_tgt[pl_cur] >= 0) {
        const Player *Q = &P[rv_tgt[pl_cur]];
        float dx = Q->px - px, dz = Q->pz - pz;
        float cxv = dx * rx + dz * rz, cz0 = dx * fx + dz * fz, yb = (Q->foot_y + 0.20f) - cam_y;
        float cyv = yb * cpitch - cz0 * spitch, czv = yb * spitch + cz0 * cpitch;
        if (czv > 0.55f) {
            tcz = clampf(czv, 0.70f, 1.6f);
            tcx = clampf(cxv * tcz / czv, -0.30f * tcz, 0.30f * tcz);
            tcy = clampf(cyv * tcz / czv, -0.75f * tcz, -0.05f * tcz);
        }
    }
    rd_sc = clampf(tcz / 0.64f, 0.9f, 2.4f);
    rd_th = 0.0f; rd_ya = 0.0f;
    rd_ox = tcx; rd_oz = tcz;
    rd_oy = tcy - 0.55f * (1.0f - e) + 0.004f * sinf(t * 1.7f);
    vm_mode = 1;
    const float LY = 0.0f, LZ = 0.0f, LR = 0.046f, X0 = -0.17f, X1 = 0.17f;
    float turns = p * 9.0f;                                          // vueltas dadas
    int nr = (int)turns; if (nr > 9) nr = 9;
    float frac = turns - (float)nr;
    // vueltas de venda ya puestas (de izquierda a derecha)
    float step = (X1 - X0) / 9.0f;
    for (int k = 0; k < nr; k++) rd_cyl_x(X0 + step * ((float)k + 0.5f), LY, LZ, step * 0.58f, LR + 0.007f, wh, (float)k * 0.7f, 1);
    float hx = X0 + step * ((float)nr + frac);                       // la mano derecha avanza girando sobre el cuerpo
    float ang = frac * 2.0f * PI_F + 0.6f;
    if (nr >= 9) { hx = X1; frac = 0.0f; }
    float hy = LY + 0.060f * cosf(ang), hz = LZ + 0.060f * sinf(ang) - 0.015f;
    static const float cyan[3] = { 40.f, 150.f, 160.f };             // manga de Steve
    float skn[3] = { hand_col[4][0], hand_col[4][1], hand_col[4][2] };
    if (nr < 9 || frac > 0.0f) {
        rd_cyl_x(hx, LY, LZ, step * 0.5f * frac + 0.004f, LR + 0.007f, wh, 0.0f, 1);               // vuelta en curso
        float a0[3], a1[3], b0[3], b1[3];                            // cinta tensa entre el rollo y el cuerpo
        float tx = hx - step * 0.3f, ty = LY + (LR + 0.007f) * cosf(ang - 1.1f), tz = LZ + (LR + 0.007f) * sinf(ang - 1.1f);
        rd_pt(hx - 0.012f, hy, hz, a0); rd_pt(hx + 0.012f, hy, hz, a1);
        rd_pt(hx + 0.012f, ty, tz, b1); rd_pt(tx, ty, tz, b0);
        V w[4]; const float *pp[4] = { a0, a1, b1, b0 };
        for (int j = 0; j < 4; j++) { w[j].x = pp[j][0]; w[j].y = pp[j][1]; w[j].z = pp[j][2]; w[j].r = wh[0]; w[j].g = wh[1]; w[j].b = wh[2]; }
        tri_cam(w[0], w[1], w[2]); tri_cam(w[0], w[2], w[3]);
        rd_cyl_x(hx, hy, hz, 0.052f, 0.030f, wh, ang * 2.0f, 1);      // rollo sujeto por el puno (sobresale a los lados)
        rd_cyl_x(hx, hy, hz, 0.004f, 0.033f, wh2, 0.0f, 0);
        const float sh_r[3] = { hx + 0.20f, hy - 0.30f, hz - 0.36f }, fi_r[3] = { hx + 0.012f, hy - 0.012f, hz - 0.034f };
        rd_limb(sh_r, fi_r, 0.036f, skn, cyan, 0.45f);               // brazo derecho (de bloque, con el puno sobre el rollo)
    }
    {   // brazo izquierdo: el puno sujeta el inicio de la venda sobre el cuerpo
        const float sh_l[3] = { X0 - 0.22f, LY - 0.30f, LZ - 0.36f }, fi_l[3] = { X0 - 0.012f, LY - 0.010f, LZ - 0.040f };
        rd_limb(sh_l, fi_l, 0.036f, skn, cyan, 0.45f);
    }
    vm_mode = 0; rd_sc = 1.0f;
}

static void draw_key(float x, float z, float fy, float a)
{
    static const float gold[3] = { 170.f, 226.f, 245.f };      // llave final: plata azulada (la amarilla es la de la puerta del noreste)
    static const float dark[3] = { 120.f, 168.f, 196.f };
    const float em = 0.32f;
    const float y0 = fy + 0.015f, y1 = fy + 0.095f;
    const float R = 0.15f;                                    // radio medio de la argolla
    for (int k = 0; k < 8; k++) {                             // argolla: 8 barras formando un octagono con hueco
        float ang = k * (PI_F / 4.0f);
        key_part(x, z, a, -0.42f + R * cosf(ang), R * sinf(ang), -(ang + PI_F * 0.5f),
                 0.068f, 0.040f, y0, y1, gold, em);
    }
    key_part(x, z, a, -0.22f, 0.0f, 0.0f, 0.030f, 0.075f, y0, y1 + 0.012f, dark, em);   // cuello
    key_part(x, z, a,  0.18f, 0.0f, 0.0f, 0.400f, 0.032f, y0, y1, gold, em);            // caña
    key_part(x, z, a,  0.50f, 0.080f, 0.0f, 0.050f, 0.050f, y0, y1, dark, em);          // dientes
    key_part(x, z, a,  0.37f, 0.070f, 0.0f, 0.040f, 0.040f, y0, y1, dark, em);
}

// ---------------- Cartel del mapa (al inicio) ----------------
static void draw_lockers(void)
{
    if (cur_layer != 0 && !climbing) return;
    static const float body[3] = {  74.f,  92.f, 100.f };
    static const float door_c[3] = { 88.f, 110.f, 120.f };
    static const float dark[3] = {  14.f,  16.f,  18.f };
    static const float knob[3] = { 190.f, 190.f, 194.f };
    for (int i = 0; i < 2 * NLOCK; i++) {
        if (i == hide_id) continue;
        float cx = lk_x(i), cz = lk_z(i);
        if (!in_view(cx, cz, 1.5f, (gfx_pd[gfx] * rd_k))) continue;
        int fxv = LKF(i, 2), fzv = LKF(i, 3);
        float hx = fxv ? LK_D * 0.5f : LK_W * 0.5f, hz = fxv ? LK_W * 0.5f : LK_D * 0.5f;
        box_rot(cx, cz, 0.0f, 0.0f, 0.0f, hx, hz, 0.0f, LK_H, body, 0.0f);
        float fo = LK_D * 0.5f + 0.012f;                                   // la puerta, pegada al frente
        float pcx = fxv * fo, pcz = fzv * fo;
        float phx = fxv ? 0.012f : LK_W * 0.5f - 0.05f, phz = fxv ? LK_W * 0.5f - 0.05f : 0.012f;
        box_rot(cx, cz, 0.0f, pcx, pcz, phx, phz, 0.06f, LK_H - 0.06f, door_c, 0.0f);
        for (int k = 0; k < 3; k++) {                                      // rejillas
            float vy = LK_H - 0.30f - k * 0.10f, vo = LK_D * 0.5f + 0.026f;
            float vhx = fxv ? 0.006f : 0.28f, vhz = fxv ? 0.28f : 0.006f;
            box_rot(cx, cz, 0.0f, fxv * vo, fzv * vo, vhx, vhz, vy, vy + 0.04f, dark, 0.0f);
        }
        float ko = LK_D * 0.5f + 0.03f, side = LK_W * 0.5f - 0.14f;      // manija
        float kx = fxv * ko + (fxv ? 0.0f : side), kz = fzv * ko + (fxv ? side : 0.0f);
        box_rot(cx, cz, 0.0f, kx, kz, fxv ? 0.02f : 0.03f, fxv ? 0.03f : 0.02f, 1.0f, 1.2f, knob, 0.0f);
    }
}

static void draw_frenzy_hud(void)
{
    if (state != 0) return;
    if (frenzy_w > 0.0f) {                                                 // cuenta atras: busca un casillero
        char cb[40];
        snprintf(cb, sizeof cb, "BUSCA UN CASILLERO: %d", (int)ceilf(frenzy_w));
        draw_text_c(H * 0.20f + 46.0f, cb, 2, GS_SETREG_RGBAQ(255, 230, 80, 0x80, 0));
    } else if (frenzy_t > 0.0f && frenzy_msg <= 0 && ((frame_no / 10) & 1)) {
        draw_text_c(H * 0.20f + 46.0f, "CORRE", 2, GS_SETREG_RGBAQ(230, 40, 30, 0x80, 0));
    }
    if (frenzy_msg <= 0) return;
    int on = (frenzy_msg > 150) ? ((frame_no / 4) & 1) : 1;               // al principio parpadea
    int a = frenzy_msg < 40 ? frenzy_msg * 255 / 40 : 255;
    if (on) {
        draw_text_c(H * 0.20f + 3.0f, "VIENE POR TI", 5, GS_SETREG_RGBAQ(0, 0, 0, 0x80, 0));
        draw_text_c(H * 0.20f, "VIENE POR TI", 5, GS_SETREG_RGBAQ(230 * a / 255, 20 * a / 255, 20 * a / 255, 0x80, 0));
    }
}

static void draw_locker_hud(void)
{
    draw_frenzy_hud();
    u64 yc = GS_SETREG_RGBAQ(255, 230, 80, 0x80, 0), wc = GS_SETREG_RGBAQ(200, 200, 205, 0x80, 0);
    if (hide_id >= 0) {                                      // dentro: oscuridad con las rendijas de la puerta
        u64 k = GS_SETREG_RGBAQ(2, 3, 4, 0x80, 0);
        float y0 = H * 0.40f, sh = 15.0f, gap = 28.0f, xa = W * 0.20f, xb = W * 0.80f;
        float yb = y0 + 2.0f * gap + sh;
        gsKit_prim_sprite(gsGlobal, 0.0f, 0.0f, W, y0, 16777150, k);
        gsKit_prim_sprite(gsGlobal, 0.0f, yb, W, H, 16777150, k);
        gsKit_prim_sprite(gsGlobal, 0.0f, y0, xa, yb, 16777150, k);
        gsKit_prim_sprite(gsGlobal, xb, y0, W, yb, 16777150, k);
        for (int i = 0; i < 2; i++) gsKit_prim_sprite(gsGlobal, xa, y0 + sh + i * gap, xb, y0 + (i + 1) * gap, 16777150, k);
        draw_text_c(H - 30.0f, "ESCONDIDO   CUADRADO: SALIR", 1, wc);
        return;
    }
    if (!map_open && code_door < 0 && pick_near() >= 0) {
        draw_text_c(H - 34.0f, pick_near() >= 100 || items[pick_near()].kind == 0 ? "CUADRADO: AGARRAR LLAVE" : "CUADRADO: AGARRAR PAPEL", 2, yc);
        return;
    }
    if (carry && !map_open && code_door < 0) {
        if (pick_near2(1) >= 0 && pick_near() < 0) { draw_text_c(H - 34.0f, "YA LLEVAS UNA LLAVE   R3: SOLTAR", 2, yc); return; }
        draw_text(20.0f, H - 20.0f, "R3: SOLTAR LLAVE", 1, GS_SETREG_RGBAQ(160, 160, 166, 0x80, 0));
    }
    if (locker_near() >= 0 && door_near() < 0 && !board_near()) {
        if (hide_hold > 0.0f) {                              // barra de carga: 1 segundo
            float bw = 120.0f, bx = (W - bw) * 0.5f, by = H - 50.0f;
            gsKit_prim_sprite(gsGlobal, bx - 2.0f, by - 2.0f, bx + bw + 2.0f, by + 8.0f, 16777000, BLACK);
            gsKit_prim_sprite(gsGlobal, bx, by, bx + bw * clampf(hide_hold, 0.0f, 1.0f), by + 6.0f, 16777010, yc);
        }
        draw_text_c(H - 34.0f, "MANTEN CUADRADO: ESCONDERTE", 2, yc);
    }
}

static void draw_map_board(float t)
{
    if (cur_layer != 0 && !climbing) return;
    if (!in_view(MAPB_X, MAPB_Z, 2.0f, (gfx_pd[gfx] * rd_k))) return;
    static const float wood[3]  = {  96.f,  66.f,  40.f };
    static const float board[3] = { 128.f,  92.f,  58.f };
    static const float paper[3] = { 222.f, 204.f, 158.f };
    static const float ink[3]   = {  70.f,  52.f,  34.f };
    static const float mark[3]  = { 200.f,  50.f,  40.f };
    float pe = has_map ? 0.20f : 0.30f + 0.10f * sinf(t * 3.0f);    // el papel llama la atencion hasta que lo tomas
    box_rot(MAPB_X - 1.0f, MAPB_Z, 0.0f, 0.0f, 0.0f, 0.07f, 0.07f, 0.0f, 2.05f, wood, 0.0f);     // postes
    box_rot(MAPB_X + 1.0f, MAPB_Z, 0.0f, 0.0f, 0.0f, 0.07f, 0.07f, 0.0f, 2.05f, wood, 0.0f);
    box_rot(MAPB_X, MAPB_Z, 0.0f, 0.0f, 0.0f, MAPB_HX, 0.05f, 0.95f, 2.05f, board, 0.0f);          // tablero
    box_rot(MAPB_X, MAPB_Z, 0.0f, 0.0f, 0.0f, MAPB_HX + 0.12f, 0.20f, 2.05f, 2.12f, wood, 0.0f);   // techito
    box_rot(MAPB_X, MAPB_Z, 0.0f, 0.0f, 0.062f, 0.95f, 0.010f, 1.10f, 1.95f, paper, pe);           // el mapa (cara hacia +z, donde apareces)
    box_rot(MAPB_X, MAPB_Z, 0.0f, 0.0f, 0.0775f, 0.03f, 0.004f, 1.18f, 1.87f, ink, pe * 0.7f);     // trazos de tinta
    box_rot(MAPB_X, MAPB_Z, 0.0f, -0.35f, 0.0775f, 0.50f, 0.004f, 1.50f, 1.54f, ink, pe * 0.7f);
    box_rot(MAPB_X, MAPB_Z, 0.0f, 0.40f, 0.0775f, 0.05f, 0.004f, 1.20f, 1.30f, mark, 0.4f);        // marca roja
}

