// Encendedor suelto en el suelo (acostado, boca arriba)
static void draw_floor_lighter(void)
{
    if (!lt_on || lt_l != cur_layer) return;
    if (!in_view(lt_x, lt_z, 0.3f, 12.0f)) return;
    const float sc = 0.00042f, ca = cosf(0.6f), sa = sinf(0.6f);     // unidades 0.25 mm x 1.7 (mide unos 8 cm)
    static V pv[LT_NV];
    float col0[3] = { 150.0f, 150.0f, 150.0f };
    for (int i = 0; i < LT_NV; i++) {
        float xm = (float)lt_v[i][0] * sc, ym = (float)lt_v[i][1] * sc, zm = ((float)lt_v[i][2] + 18.0f) * sc;
        pv[i] = mk(lt_x + ca * xm - sa * ym, foot_y + zm, lt_z + sa * xm + ca * ym, col0, 0.30f);
    }
    for (int i = 0; i < LT_NT; i++) {
        if (lt_nz[i] < -55) continue;                                // caras de abajo
        V a = pv[lt_t[i][0]], b = pv[lt_t[i][1]], c = pv[lt_t[i][2]];
        V *q3[3] = { &a, &b, &c };
        for (int j = 0; j < 3; j++) {                                // color de la cara x luz de cada vertice
            q3[j]->r *= (float)lt_c[i][0] / 150.0f; q3[j]->g *= (float)lt_c[i][1] / 150.0f; q3[j]->b *= (float)lt_c[i][2] / 150.0f;
        }
        tri_cam(a, b, c);
    }
}

